/// Bounded iterative reachability: can `from` reach `to` over `succs`?
fn cfg_reaches(succs: &[Vec<usize>], from: usize, to: usize) -> bool {
    if from == to {
        return true;
    }
    let mut seen = vec![false; succs.len()];
    let mut stack = vec![from];
    seen[from] = true;
    while let Some(n) = stack.pop() {
        for &s in &succs[n] {
            if s == to {
                return true;
            }
            if s < seen.len() && !seen[s] {
                seen[s] = true;
                stack.push(s);
            }
        }
    }
    false
}

/// Classify one method's structure and fold it into the census. Called once per
/// rendered method, from the render entry (NOT per walk: the binding-discovery
/// walk builds a second `Structurer` over the same CFG, so counting there would
/// double every number).
fn classify_structure(sc: &StructuredCfg, loops: &HashMap<usize, LoopInfo>, insns: &[Insn]) {
    use std::sync::atomic::Ordering;
    let m = &STRUCT_CENSUS;
    m.methods.fetch_add(1, Ordering::Relaxed);
    m.blocks
        .fetch_add(sc.blocks.len() as u64, Ordering::Relaxed);

    // Irreducible edges: non-dominated edges that still close a cycle.
    let n = sc.blocks.len();
    let mut irre = 0u64;
    for t in 0..n {
        for &h in &sc.full_succ[t] {
            if h >= n || h == t {
                continue;
            }
            // does h dominate t? (walk t's idom chain)
            let mut cur = Some(t);
            let mut dominated = false;
            let mut hops = 0usize;
            while let Some(c) = cur {
                if c == h {
                    dominated = true;
                    break;
                }
                cur = sc.idom[c];
                hops += 1;
                if hops > n + 1 {
                    break;
                }
            }
            if dominated {
                continue;
            }
            // Not dominated: irreducible only if it is part of a CYCLE, i.e.
            // the nominal header can get back to this block.
            if cfg_reaches(&sc.full_succ, h, t) {
                irre += 1;
            }
        }
    }
    if irre > 0 {
        m.irreducible_methods.fetch_add(1, Ordering::Relaxed);
        m.irreducible_edges.fetch_add(irre, Ordering::Relaxed);
    }

    m.loops.fetch_add(loops.len() as u64, Ordering::Relaxed);
    let multi = loops.values().filter(|l| l.latches.len() > 1).count() as u64;
    if multi > 0 {
        m.multi_latch_loops.fetch_add(multi, Ordering::Relaxed);
        m.multi_latch_methods.fetch_add(1, Ordering::Relaxed);
    }

    let mut sw_ops = 0u64;
    let mut sw_targets = 0u64;
    let mut disp = 0u64;
    for i in insns {
        match &i.op {
            Op::Switch(targets) => {
                sw_ops += 1;
                sw_targets += targets.len() as u64;
            }
            // At render time a recovered jump table has already become
            // `Op::Switch`, so any remaining `IndirectCall` is a dispatch whose
            // table was NOT recovered (the L1 case).
            Op::IndirectCall => disp += 1,
            _ => {}
        }
    }
    m.switch_ops.fetch_add(sw_ops, Ordering::Relaxed);
    m.switch_targets.fetch_add(sw_targets, Ordering::Relaxed);
    if disp > 0 {
        m.dispatch_lost_methods.fetch_add(1, Ordering::Relaxed);
        m.dispatch_lost_ops.fetch_add(disp, Ordering::Relaxed);
    }
}

// ---------------------------------------------------------------------------
// Fallback census: how many methods are a MARKER rather than code
// ---------------------------------------------------------------------------
//
// The per-method verdicts classify each rendered body by what is WRONG with it
// (an unnamed value, a missing region, an unresolved dispatch). That leaves a
// prior question unanswered: how many bodies are not translations at all? Those
// are the four marker strings below, and they have very different causes and
// very different fixes — a size cap, an unreadable body, an unsupported
// pattern, or a body that recovered but structured to nothing. Counting them
// together as "declined" hid which one to work on.
pub struct FallbackCensus {
    /// Methods considered at all (so the counts below have a denominator).
    pub attempted: std::sync::atomic::AtomicU64,
    /// Bigger than the text pass's ceiling: skipped on purpose, not a failure —
    /// the IR pipeline may still have decompiled it.
    pub too_large: std::sync::atomic::AtomicU64,
    /// The method's bytes could not be read from the image.
    pub bytes_unreadable: std::sync::atomic::AtomicU64,
    /// Recovery returned no IR: the lifter met a shape it does not model.
    pub unsupported_pattern: std::sync::atomic::AtomicU64,
    /// IR recovered, but the structurer emitted no statements — an empty shell.
    pub empty_body: std::sync::atomic::AtomicU64,
}

pub static FALLBACK: FallbackCensus = FallbackCensus {
    attempted: std::sync::atomic::AtomicU64::new(0),
    too_large: std::sync::atomic::AtomicU64::new(0),
    bytes_unreadable: std::sync::atomic::AtomicU64::new(0),
    unsupported_pattern: std::sync::atomic::AtomicU64::new(0),
    empty_body: std::sync::atomic::AtomicU64::new(0),
};

/// One line per fallback reason, with the share of attempted methods.
pub fn fallback_census_report() -> String {
    use std::sync::atomic::Ordering::Relaxed;
    let attempted = FALLBACK.attempted.load(Relaxed);
    if attempted == 0 {
        return String::new();
    }
    let g = |a: &std::sync::atomic::AtomicU64| a.load(Relaxed);
    let pct = |n: u64| 100.0 * n as f64 / attempted as f64;
    let too_large = g(&FALLBACK.too_large);
    let unreadable = g(&FALLBACK.bytes_unreadable);
    let unsupported = g(&FALLBACK.unsupported_pattern);
    let empty = g(&FALLBACK.empty_body);
    let total = too_large + unreadable + unsupported + empty;
    let mut s = String::new();
    s.push_str(&format!(
        "[fallback] bodies that are a MARKER, not a translation: {total} of {attempted} attempted ({:.1}%)\n",
        pct(total)
    ));
    s.push_str(&format!(
        "[fallback]   too large for the text pass ({too_large}, {:.1}%) — skipped on purpose; the IR pipeline may still have handled it\n",
        pct(too_large)
    ));
    s.push_str(&format!(
        "[fallback]   body bytes unreadable ({unreadable}, {:.1}%) — image/offset problem, not a decompiler problem\n",
        pct(unreadable)
    ));
    s.push_str(&format!(
        "[fallback]   unsupported pattern ({unsupported}, {:.1}%) — NO IR: a lifter gap (this is the one that is a real decompiler bug)\n",
        pct(unsupported)
    ));
    s.push_str(&format!(
        "[fallback]   recovered but structured to nothing ({empty}, {:.1}%) — an empty body shell, a structurer gap\n",
        pct(empty)
    ));
    s
}

/// Human-readable structural census. Printed next to the fidelity verdicts, so
/// "64% of methods contain a goto" can be read together with the shapes that
/// produced them.
pub fn struct_census_report() -> String {
    use std::sync::atomic::Ordering;
    let g = |a: &std::sync::atomic::AtomicU64| a.load(Ordering::Relaxed);
    let m = &STRUCT_CENSUS;
    let n = g(&m.methods);
    if n == 0 {
        return String::new();
    }
    let pct = |num: u64, den: u64| {
        if den == 0 {
            0.0
        } else {
            100.0 * num as f64 / den as f64
        }
    };
    let mut s = String::new();
    s.push_str(&format!(
        "[struct] shapes that force a `goto` ({n} methods, {} blocks):\n",
        g(&m.blocks)
    ));
    s.push_str(&format!(
        "[struct]   irreducible edges (a cycle no single header dominates): {} in {} methods ({:.1}%)\n",
        g(&m.irreducible_edges),
        g(&m.irreducible_methods),
        pct(g(&m.irreducible_methods), n)
    ));
    s.push_str(&format!(
        "[struct]   natural loops: {}; multiply-latched ({} loops in {} methods)\n",
        g(&m.loops),
        g(&m.multi_latch_loops),
        g(&m.multi_latch_methods)
    ));
    s.push_str(&format!(
        "[struct]   if with no reconverging join (find_merge gave up): {} sites; \
         join from the branch HEADER's ipdom: {}; REFUSED (join not reachable from both arms): {}\n",
        g(&m.merge_fail_total),
        g(&m.merge_via_header),
        g(&m.merge_not_common)
    ));
    s.push_str(&format!(
        "[struct]   switches: {} recovered tables, {} case targets | unrecovered dispatch: {} ops in {} methods ({:.1}%)\n",
        g(&m.switch_ops),
        g(&m.switch_targets),
        g(&m.dispatch_lost_ops),
        g(&m.dispatch_lost_methods),
        pct(g(&m.dispatch_lost_methods), n)
    ));
    s.push_str(&format!(
        "[struct]   `goto` statements requested by the walk: {} (upper bound; the final text keeps fewer)\n",
        g(&m.goto_sites)
    ));
    // The split that makes the total actionable: which CALL SITE produced each
    // goto. Sorted biggest-first by hand (the counts are few and the order is
    // part of the report's meaning — the top line is where the leverage is).
    let mut reasons: Vec<(GotoReason, u64)> = [
        GotoReason::NoMerge,
        GotoReason::Backward,
        GotoReason::AlreadyEmitted,
        GotoReason::Dispatch,
        GotoReason::MergeEmitted,
        GotoReason::SkipEmpty,
        GotoReason::FlatGuard,
        GotoReason::HandlerPad,
        GotoReason::Uncategorised,
        GotoReason::LoopExit,
        GotoReason::SplitBoundary,
    ]
    .into_iter()
    .map(|r| (r, g(&m.goto_by_reason[r.idx()])))
    .collect();
    s.push_str(&format!(
        "[struct]   shared return tails duplicated instead of jumped to: {}\n",
        g(&m.tail_duplications)
    ));
    s.push_str(&format!(
        "[struct]   gotos folded to void returns: {}\n",
        g(&m.goto_return_folds)
    ));
    s.push_str(&format!(
        "[struct]   gotos folded to break: {}\n",
        g(&m.goto_break_folds)
    ));
    s.push_str(&format!(
        "[struct]   shared-if suffix folds: {}/{}; refused={}\n",
        g(&m.shared_if_suffix_hits),
        g(&m.shared_if_suffix_attempts),
        g(&m.shared_if_suffix_refused)
    ));
    s.push_str(&format!(
        "[struct]   switch-arm goto case rewrites: {}/{}; refused non-case targets={}\n",
        g(&m.case_goto_hits),
        g(&m.case_goto_attempts),
        g(&m.case_goto_refused)
    ));
    s.push_str(&format!(
        "[struct]   flat-guard chains: {}; guard shells fused into `||`: {}; vacuous (fall arm empty): {}\n",
        g(&m.flat_guard_chains),
        g(&m.flat_guard_fused),
        g(&m.flat_guard_empty_fall)
    ));
    s.push_str(&format!(
        "[struct]     flat guards rewritten without goto: {}; refused: labels={} declarations={} depth={} (total={})\n",
        g(&m.flat_guard_structured),
        g(&m.flat_guard_refused_label),
        g(&m.flat_guard_refused_declaration),
        g(&m.flat_guard_refused_depth),
        g(&m.flat_guard_scope_refused)
    ));
    s.push_str(&format!(
        "[struct]     vacuous because: same block both edges={} | false edge leaves the region (should be 0 — carried as a goto)={} | emit_arm produced nothing={}\n",
        g(&m.flat_empty_same),
        g(&m.flat_empty_stop),
        g(&m.flat_empty_other)
    ));
    s.push_str(&format!(
        "[struct]     dropped `c == false` edges CARRIED explicitly as a goto: {}\n",
        g(&m.flat_fall_edge_kept)
    ));
    reasons.sort_by(|a, b| b.1.cmp(&a.1));
    for (r, c) in reasons {
        s.push_str(&format!(
            "[struct]     goto from {}: {} ({:.1}% of gotos)\n",
            r.label(),
            c,
            pct(c, g(&m.goto_sites))
        ));
    }
    s
}

/// Blocks the CFG can reach from the entry, over taken/fall edges plus every
/// recovered `switch` arm.
///
/// A `switch` block has no taken/fall — its arms are reachable only through the
/// jump table — so they must count as reachable here or every correctly-emitted
/// switch would look like dead code to the coverage repair.
/// Blocks reachable from the entry — see [`reachable_blocks`] for the raw set.
fn reachable_blocks_entry(sc: &StructuredCfg, insns: &[Insn]) -> Vec<bool> {
    reachable_blocks(sc, insns)
}

/// Does the block at `b` hold a branch INTO `adopted` other than the method's
/// own entry block?
///
/// The exclusion of block 0 is what keeps a THUNK out: an IL2CPP adjustor /
/// runtime-invoker stub is a bare `b <method entry>`, and such a stub sitting
/// in the gap after this method would otherwise look like this method's cold
/// region. A cold region resumes INSIDE the body, never at its first block.
fn branches_into(succs: &[Vec<usize>], b: usize, adopted: &[bool]) -> bool {
    succs[b]
        .iter()
        .any(|&s| s != 0 && s < adopted.len() && adopted[s])
}

/// The entry-reachable set PLUS the blocks of the method that no recovered edge
/// from the entry can reach: its out-of-line cold region.
///
/// LLVM lays a function's exception landing pads and cold blocks out AFTER the
/// body's last `ret`, and they are entered by the UNWINDER — which a CFG built
/// from branches cannot see. They are therefore "CFG-unreachable" while being
/// this method's own code, and every call in them was missing from the text:
/// 90 of the 198 methods still flagged as dropping calls in the reference
/// sample, holding 1,107 native `bl` between them.
///
/// Ownership is proven by an edge, never assumed from layout. A component of
/// unreachable blocks is adopted only when one of its blocks BRANCHES INTO the
/// adopted set (`branches_into`, excluding the entry block). A different
/// function never branches into the middle of this one's body, so `cbz x0,
/// 0x1DD7B60` from the cold region at 0x1DD7CA8 into
/// `ConstraintCollection.Clear`'s own body is proof they are one function —
/// which is why hand-inspecting that method and concluding "the leftover blocks
/// are a neighbour's code, they have no edge INTO them" was wrong in the other
/// direction: no edge in says nothing, an edge OUT decides.
///
/// The fixpoint matters: a cold region's landing pads can chain, so a component
/// reachable only from an already-adopted one must be adopted too.
///
/// Adoption is a measurement+emission change, not a structuring one — the
/// blocks go through [`Structurer::coverage_repair`], which renders them FLAT
/// behind a marker, so no loop body is duplicated and no call is expanded
/// twice.
fn adjoined_blocks(sc: &StructuredCfg, insns: &[Insn]) -> Vec<bool> {
    let n = sc.blocks.len();
    let mut adopted = reachable_blocks_entry(sc, insns);
    if n == 0 {
        return adopted;
    }
    // Successor lists (taken, fall, and every switch target) and their reverse,
    // built ONCE so the component walk below is linear in the CFG size.
    let mut succs: Vec<Vec<usize>> = Vec::with_capacity(n);
    for b in 0..n {
        let mut succ: Vec<usize> = [sc.blocks[b].succ_taken, sc.blocks[b].succ_fall]
            .into_iter()
            .flatten()
            .filter(|&s| s < n)
            .collect();
        if let Op::Switch(targets) = &insns[sc.blocks[b].end - 1].op {
            for t in targets {
                if let Some(&s) = sc.block_of.get(*t) {
                    if s < n {
                        succ.push(s);
                    }
                }
            }
        }
        succs.push(succ);
    }
    let mut preds: Vec<Vec<usize>> = vec![Vec::new(); n];
    for (b, ss) in succs.iter().enumerate() {
        for &s in ss {
            preds[s].push(b);
        }
    }
    // Components of the not-yet-adopted blocks. UNDIRECTED over the CFG's edges:
    // a landing pad reached from another pad has to land in the same component,
    // or the fixpoint below needs one pass per chain link.
    let mut component: Vec<usize> = (0..n)
        .map(|b| if adopted[b] { b } else { usize::MAX })
        .collect();
    let mut comps: Vec<Vec<usize>> = Vec::new();
    for root in 0..n {
        if adopted[root] || component[root] != usize::MAX {
            continue;
        }
        let id = comps.len();
        let mut members = Vec::new();
        let mut stack = vec![root];
        component[root] = id;
        while let Some(b) = stack.pop() {
            members.push(b);
            for &s in succs[b].iter().chain(preds[b].iter()) {
                if !adopted[s] && component[s] == usize::MAX {
                    component[s] = id;
                    stack.push(s);
                }
            }
        }
        comps.push(members);
    }
    loop {
        let mut changed = false;
        for members in &comps {
            if members.iter().all(|&b| adopted[b]) {
                continue;
            }
            if members.iter().any(|&b| branches_into(&succs, b, &adopted)) {
                for &b in members {
                    adopted[b] = true;
                }
                changed = true;
            }
        }
        if !changed {
            break;
        }
    }
    adopted
}

fn reachable_blocks(sc: &StructuredCfg, insns: &[Insn]) -> Vec<bool> {
    let mut seen = vec![false; sc.blocks.len()];
    let mut stack: Vec<usize> = Vec::new();
    if !seen.is_empty() {
        seen[0] = true;
        stack.push(0);
    }
    while let Some(b) = stack.pop() {
        let mut succ: Vec<usize> = [sc.blocks[b].succ_taken, sc.blocks[b].succ_fall]
            .into_iter()
            .flatten()
            .collect();
        if let Op::Switch(targets) = &insns[sc.blocks[b].end - 1].op {
            for t in targets {
                if let Some(&s) = sc.block_of.get(*t) {
                    succ.push(s);
                }
            }
        }
        for s in succ {
            if s < sc.blocks.len() && !seen[s] {
                seen[s] = true;
                stack.push(s);
            }
        }
    }
    seen
}

/// Short op name, for the `ILR_COV` coverage report.
fn self_op_name(op: &Op) -> &'static str {
    match op {
        Op::CondJump(_) => "CondJump",
        Op::Jump(_) => "Jump",
        Op::Return => "Return",
        Op::Throw => "Throw",
        Op::Switch(_) => "Switch",
        Op::IndirectCall => "IndirectCall",
        Op::Call | Op::CallVoid => "Call",
        _ => "other",
    }
}

/// `(blocks never walked, total blocks)` for this thread's last render.
pub(crate) fn unemitted_blocks() -> (usize, usize) {
    (
        UNEMITTED_BLOCKS.with(|c| c.get()),
        TOTAL_BLOCKS.with(|c| c.get()),
    )
}

/// `(def resolutions, recursion high-water mark)` for this thread.
///
/// Exposed so the regression test for the def-cycle guard can assert that a
/// loop-carried def is referenced instead of expanded, without timing anything
/// or parsing the rendered text.
#[cfg(test)]
pub(crate) fn def_resolution_counts() -> (u64, u64) {
    (DEF_CALLS.with(|c| c.get()), DEF_MAXDEPTH.with(|m| m.get()))
}

/// Test hook: resolve a USE of local `v` at `use_insn` through the real
/// inlining machinery and render the resulting expression.
///
/// The cycle guard lives inside `MethodCtx`, and a full render needs a
/// structurable CFG, so this drives the resolver directly — which is what the
/// guard actually protects.
#[cfg(test)]
pub(crate) fn resolve_local_use_for_test(
    ir: &super::RecoveredIr,
    use_insn: usize,
    v: u32,
) -> String {
    let parent_chain: HashMap<i32, Vec<i32>> = HashMap::new();
    let ctx = MethodCtx::build(&ir.insns, &ir.table, -1, &parent_chain, false, None);
    ctx.cur_insn.set(use_insn);
    let e = ctx.operand_expr(&Operand::Local(v), 0);
    let mut buf = String::new();
    e.render(&mut buf);
    buf
}

/// Zero the counters returned by [`def_resolution_counts`].
#[cfg(test)]
pub(crate) fn reset_def_resolution_counts() {
    DEF_CALLS.with(|c| c.set(0));
    DEF_DEPTH.with(|c| c.set(0));
    DEF_MAXDEPTH.with(|m| m.set(0));
}

/// `ILR_RSSDBG=1`: print the process RSS at the start and end of every method,
/// so a memory blow-up can be attributed to the method that caused it.
fn rss_probe(tag: &str, rva: u64, size: usize) {
    let rss_kb = std::fs::read_to_string("/proc/self/statm")
        .ok()
        .and_then(|s| {
            s.split_whitespace()
                .nth(1)
                .and_then(|p| p.parse::<u64>().ok())
        })
        .map(|pages| pages * 4)
        .unwrap_or(0);
    eprintln!("[rss] {tag} {rva:#x} size={size} rss={rss_kb}KB");
}

/// Optional method-count cap for the determinism gate; see the strided sample
/// at the `ILR_DET_LIMIT` site in [`decompile_methods_to_csharp`].
fn det_limit() -> Option<usize> {
    std::env::var("ILR_DET_LIMIT")
        .ok()
        .and_then(|v| v.trim().parse::<usize>().ok())
}

/// Optional wall-clock safety valve for the whole pipeline.
///
/// OFF by default, and that is the point: a wall-clock cut-off makes the
/// emitted body depend on machine load, so the same binary yields different
/// text on different runs. Set `ILR_TIME_LIMIT=<ms>` to re-enable it when a
/// hard runtime bound matters more than reproducibility — the determinism gate
/// (`scripts/det_gate.sh`) will then report the difference instead of hiding it.
fn time_limit_ms() -> Option<u64> {
    std::env::var("ILR_TIME_LIMIT")
        .ok()
        .and_then(|v| v.trim().parse::<u64>().ok())
        .filter(|ms| *ms > 0)
}

/// Render-phase wall-clock budget; see [`time_limit_ms`].
fn render_deadline() -> Option<std::time::Instant> {
    time_limit_ms().map(|ms| std::time::Instant::now() + std::time::Duration::from_millis(ms))
}

/// FNV-1a 64. Deliberately not `DefaultHasher`: this digest is compared across
/// SEPARATE PROCESSES (see [`det_write_manifest`]), and a hand-rolled constant
/// seed removes any question about seed stability or std's internals changing.
fn fnv1a64(bytes: &[u8]) -> u64 {
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for &b in bytes {
        h ^= b as u64;
        h = h.wrapping_mul(0x0000_0100_0000_01b3);
    }
    h
}

/// Determinism gate: write `<rva>\t<digest>\t<bytes>` per recovered method,
/// sorted by RVA, to `path` (`ILR_DET_MANIFEST=<path>`).
///
/// Run the dumper twice in two separate processes and diff the two manifests.
/// Every ordering leak in the pipeline — a `HashMap` iterated to build a
/// statement list, a `HashSet` seed leaking into a decision, an unstable sort,
/// a wall-clock cut-off — shows up as a differing digest next to the RVA that
/// produced it. This is the exhaustive form of "is the decompiler
/// deterministic?": it does not depend on anyone remembering which map got
/// iterated, and it cannot be satisfied by fixing only the maps we found today.
fn det_write_manifest(path: &str, results: &HashMap<u64, String>) {
    let mut rows: Vec<(u64, u64, usize)> = results
        .iter()
        .map(|(rva, text)| (*rva, fnv1a64(text.as_bytes()), text.len()))
        .collect();
    rows.sort_unstable_by_key(|r| r.0);
    let mut out = String::with_capacity(rows.len() * 34);
    for (rva, digest, len) in rows {
        out.push_str(&format!("{rva:016x}\t{digest:016x}\t{len}\n"));
    }
    match std::fs::write(path, out) {
        Ok(()) => eprintln!("[det] manifest: {} methods -> {path}", results.len()),
        Err(e) => eprintln!("[det] manifest write FAILED: {e}"),
    }
}

// ---------------------------------------------------------------------------
// Pattern catalog — the C#-construct binding layer (data-driven)
// ---------------------------------------------------------------------------
//
// The lifters decode native instructions into the shared IR and the
// structurer/rewrite passes already rebuild statements, but each "dirty
// output" fix used to be a one-off `if` arm buried somewhere. This catalog
// makes those fixes DATA: every binding is a named, documented entry in one
// registry with a trigger shape, a condition, a rewrite, and (later) a
// before/after spec test. Coverage compounds by appending entries, exactly
// like a "C# ⇄ assembly construct table" — without paying JSON parse costs
// in the per-method hot path or losing type safety.
//
// Design notes:
//  * Post-order: children are bound first, then this list's bindings run.
//  * Each binding is iterated to a fixpoint (bounded) per list.
//  * A failed match ALWAYS leaves the lower-level sequence untouched
//    (the decompiler's "accurate lower-level > plausible-but-wrong" rule).
//  * Bindings that need *types* (e.g. `x == 0` vs `x == null`) run at
//    statement time where `MethodCtx`/local types are still reachable, not
//    here — this module only sees the pure Expr/Stmt tree.
pub mod catalog {
    use super::{CmpKind, Expr, Stmt};

    struct Binding {
        name: &'static str,
        /// How confident the rewrite is: Exact / Metadata / Pattern /
        /// Approximate. Drives optional provenance comments on emission.
        run: fn(&mut Vec<Stmt>) -> usize,
    }

    /// Registry — APPEND NEW BINDINGS HERE. Order matters: earlier entries
    /// run first. Keep each entry small + auditable + testable in isolation.
    const BINDINGS: &[Binding] = &[
        Binding {
            name: "fold_allocation_null_test",
            run: fold_allocation_null_test,
        },
        // QUEUED ENTRIES (roadmap — each gets its own binding fn):
        //  * event_subscribe_cas: Delegate.Combine/Remove retry loop →
        //    `evt += handler` / `evt -= handler` (trigger: CAS call + field
        //    reload in a single-back-edge loop)
        //  * delegate_ctor_args: new Action<T>(this, method) — fill the
        //    duplicated `Local, Local` ctor operands from the (target,
        //    method-cell) loads that precede the call
        //  * icall_signature: fn_* trampoline calls get parameter/return
        //    types from the binary's icall/rgctx tables (metadata API layer)
        //  * null_vs_zero: `x == 0` → `x == null` where the local's type
        //    is a reference (needs MethodCtx — run at statement time)
        //  * fp_field_store: FP-only method bodies whose only effects are
        //    float field stores (currently dropped pre-render)
        //  * for_loop_shape: init/cond/inc/backedge → `for` (needs the
        //    loop header's pre-header defs)
    ];

    pub fn apply(stmts: &mut Vec<Stmt>) {
        // post-order: children first
        for s in stmts.iter_mut() {
            match s {
                Stmt::If {
                    then_body,
                    else_body,
                    ..
                } => {
                    apply(then_body);
                    apply(else_body);
                }
                Stmt::While { body, .. } => apply(body),
                Stmt::DoWhile { body, .. } => apply(body),
                Stmt::Try {
                    try_body,
                    catches,
                    finally_body,
                } => {
                    apply(try_body);
                    for (_, body) in catches.iter_mut() {
                        apply(body);
                    }
                    if let Some(f) = finally_body {
                        apply(f);
                    }
                }
                _ => {}
            }
        }
        // then this list's bindings, each to a bounded fixpoint.
        // ILR_BINDINGS=1 reports per-binding rewrite counts — the only way to
        // tell which catalog entry is actually doing work on real methods, and
        // which one silently never fires.
        let tally = crate::recovery::env_flags::flag("ILR_BINDINGS");
        for b in BINDINGS {
            let mut iters = 0;
            let mut hits = 0usize;
            loop {
                let n = (b.run)(stmts);
                hits += n;
                if n == 0 || iters >= 8 {
                    break;
                }
                iters += 1;
            }
            if tally && hits > 0 {
                eprintln!("[bindings] {}: {hits} rewrites in {iters} passes", b.name);
            }
        }
    }

    /// Is `e` an allocation expression (`new T(...)` / `new T[n]`)?
    fn is_alloc(e: &Expr) -> bool {
        matches!(e, Expr::NewObj(..) | Expr::NewArr(..))
    }

    /// Fold `new T() == 0/null` (and `!=`) to false/true.
    ///
    /// A managed allocation can never hand back a null *test that carries
    /// C#-level logic*: il2cpp may abort on OOM, but in the source language
    /// `new` never yields null, so an `if (new object() == 0) { L: }` shell
    /// left behind by failed call-merge recovery is dead and collapses. The
    /// Renderer then drops the constant-false `if` entirely (and the label
    /// inside with it), and `drop_unreachable_gotos` sweeps any dangling
    /// goto that pointed at that label.
    fn fold_allocation_null_test(stmts: &mut Vec<Stmt>) -> usize {
        let mut n = 0usize;
        for stmt in stmts.iter_mut() {
            let cond = match stmt {
                Stmt::If { cond, .. } | Stmt::While { cond, .. } => cond,
                Stmt::DoWhile { cond, .. } => cond,
                _ => continue,
            };
            let Expr::Cmp(k, a, b) = cond else { continue };
            let alloc_zero =
                |x: &Expr, y: &Expr| is_alloc(x) && matches!(y, Expr::Int(0) | Expr::Null);
            let eq = matches!(k, CmpKind::Eq);
            let ne = matches!(k, CmpKind::Ne);
            if alloc_zero(a, b) || alloc_zero(b, a) {
                if eq || ne {
                    *cond = Expr::Bool(ne); // Eq → false, Ne → true
                    n += 1;
                }
            }
        }
        n
    }
}

// ---------------------------------------------------------------------------
// Reaching-definition invariant tests
// ---------------------------------------------------------------------------
//
// These lock the φ-point rule: when two DIFFERENT definitions of the same
// local reach a join, the join's IN set must contain NO entry for that local.
// Every consumer depends on it — `compute_var_reads` marks such locals as
// variables and `inline_local_at` renders the name, so the value is correct
// on every path. A meet that lets the last predecessor win instead makes a
// shared `ret` return one arbitrary path's expression (see the
// GetEffectiveSchemaType @0x1f4e79c regression below).
#[cfg(test)]
mod reaching_def_tests {
    use super::*;
    use crate::recovery::ir::{CompareKind, Op, Operand};

    fn cond(scratch: u32, target: usize, address: u64) -> Vec<Insn> {
        vec![
            Insn {
                op: Op::Compare(CompareKind::NotEqual),
                operands: vec![
                    Operand::Local(scratch),
                    Operand::Immediate(1),
                    Operand::Immediate(0),
                ],
                dest_type: None,
                address,
            },
            Insn {
                op: Op::CondJump(target),
                operands: vec![Operand::Local(scratch)],
                dest_type: None,
                address,
            },
        ]
    }

    /// THREE predecessors define `v1` differently and all reach the `Return`.
    /// The join must NOT claim a single reaching def.
    ///
    /// Three is the minimum that exposes the bug: with two, the meet's
    /// remove-on-conflict happened to leave the map empty, and only the
    /// THIRD predecessor re-inserted a def — which is exactly what happened
    /// on real methods (the shared `ret` in GetEffectiveSchemaType @0x1f4e79c
    /// has five predecessors, and the fifth won).
    #[test]
    fn conflicting_defs_at_join_are_dropped() {
        let scratch = u32::MAX - 1;
        let mut insns: Vec<Insn> = Vec::new();
        // B0: v1 = v3 ; if (… != 0) goto 9 (the join)
        insns.push(Insn::move_(Operand::Local(1), Operand::Local(3), 0x1000));
        insns.extend(cond(scratch, 9, 0x1004));
        // B1: v1 = v4 ; if (… != 0) goto 9
        insns.push(Insn::move_(Operand::Local(1), Operand::Local(4), 0x1008));
        insns.extend(cond(scratch, 9, 0x100c));
        // B2: v1 = v5 ; goto 9
        insns.push(Insn::move_(Operand::Local(1), Operand::Local(5), 0x1010));
        insns.push(Insn {
            op: Op::Jump(9),
            operands: vec![],
            dest_type: None,
            address: 0x1014,
        });
        // filler so the join gets its own block
        insns.push(Insn {
            op: Op::Nop,
            operands: vec![],
            dest_type: None,
            address: 0x1018,
        });
        // B4: the join (three predecessors)
        insns.push(Insn {
            op: Op::Return,
            operands: vec![Operand::Local(1)],
            dest_type: None,
            address: 0x101c,
        });

        let r = compute_reaching_definitions(&insns, None);
        // Find the join block (the one holding the Return).
        let ret_idx = insns.len() - 1;
        let join = r
            .blocks
            .iter()
            .position(|&(s, e)| ret_idx >= s && ret_idx < e)
            .expect("return block");
        assert!(
            !r.gen_kill_in[join].contains_key(&1),
            "v1 has conflicting defs reaching the join — IN must have no entry, got {:?}",
            r.gen_kill_in[join].get(&1)
        );
    }

    /// A single definition reaching a join still resolves (the fix must not
    /// throw away unambiguous merges).
    #[test]
    fn single_reaching_def_survives_join() {
        let scratch = u32::MAX - 1;
        let mut insns: Vec<Insn> = Vec::new();
        // B0: v1 = v3 ; if (… != 0) goto 7
        insns.push(Insn::move_(Operand::Local(1), Operand::Local(3), 0x2000));
        insns.extend(cond(scratch, 7, 0x2004));
        // B1: v2 = v4 ; goto 7   (does NOT touch v1)
        insns.push(Insn::move_(Operand::Local(2), Operand::Local(4), 0x2008));
        insns.push(Insn {
            op: Op::Jump(7),
            operands: vec![],
            dest_type: None,
            address: 0x200c,
        });
        insns.push(Insn {
            op: Op::Nop,
            operands: vec![],
            dest_type: None,
            address: 0x2010,
        });
        insns.push(Insn {
            op: Op::Nop,
            operands: vec![],
            dest_type: None,
            address: 0x2014,
        });
        insns.push(Insn {
            op: Op::Return,
            operands: vec![Operand::Local(1)],
            dest_type: None,
            address: 0x2018,
        });

        let r = compute_reaching_definitions(&insns, None);
        let ret_idx = insns.len() - 1;
        let join = r
            .blocks
            .iter()
            .position(|&(s, e)| ret_idx >= s && ret_idx < e)
            .expect("return block");
        assert_eq!(
            r.gen_kill_in[join].get(&1).copied(),
            Some(0),
            "the only def of v1 that reaches the join is insn 0"
        );
    }
}

// ---------------------------------------------------------------------------
// Structurer goto-reduction tests (Worker I)
// ---------------------------------------------------------------------------
//
// Safety proof (inert on well-formed IR): `fold_branch_over_join` keeps its
// exact gates (lone goto, noise-only else, label later in THIS list, no flat
// label inside) and only changes in two ways, both of which fold strictly
// more of what the old code already accepted: (a) siblings are visited
// reverse, so a chain `[G1, B1, G2, B2, J:]` folds G2 first and then G1
// instead of stranding G2 cross-level (forward order left 1 goto, reverse
// leaves 0); (b) recursion extends to every compound statement (Try, Switch,
// For, Using, Lock, ForEach) so guards inside handlers/arms fold with the
// same gates instead of never being visited. No write moves, no condition
// deleted (the predicate is inverted, not dropped), the join label is kept
// so every other `goto L` still lands. Well-formed diamonds without guard
// chains render identically.
#[cfg(test)]
mod structurer_goto_tests {
    use super::*;

    fn var(n: &str) -> Expr {
        Expr::Var(n.into())
    }

    fn guard(c: &str, label: &str) -> Stmt {
        Stmt::If {
            cond: var(c),
            then_body: vec![Stmt::Goto(label.into())],
            else_body: vec![],
        }
    }

    fn count_gotos(stmts: &[Stmt]) -> usize {
        let mut n = 0usize;
        for s in stmts {
            match s {
                Stmt::Goto(_) => n += 1,
                Stmt::If {
                    then_body,
                    else_body,
                    ..
                } => {
                    n += count_gotos(then_body);
                    n += count_gotos(else_body);
                }
                Stmt::While { body, .. } | Stmt::DoWhile { body, .. } => {
                    n += count_gotos(body);
                }
                Stmt::Try {
                    try_body,
                    catches,
                    finally_body,
                } => {
                    n += count_gotos(try_body);
                    for (_, b) in catches {
                        n += count_gotos(b);
                    }
                    if let Some(f) = finally_body {
                        n += count_gotos(f);
                    }
                }
                Stmt::Switch {
                    cases,
                    tail,
                    default,
                    ..
                } => {
                    for (_, b) in cases {
                        n += count_gotos(b);
                    }
                    if let Some(arm) = default {
                        n += count_gotos(arm);
                    }
                    n += count_gotos(tail);
                }
                Stmt::For { body, .. }
                | Stmt::Using { body, .. }
                | Stmt::Lock { body, .. }
                | Stmt::ForEach { body, .. } => n += count_gotos(body),
                _ => {}
            }
        }
        n
    }

    #[test]
    fn goto_to_return_folds_globally_but_never_in_finally() {
        let mut stmts = vec![
            Stmt::If {
                cond: var("nested"),
                then_body: vec![Stmt::Goto("Lexit".into())],
                else_body: vec![],
            },
            Stmt::While {
                cond: var("again"),
                body: vec![Stmt::Goto("Lexit".into())],
            },
            Stmt::Label("Lexit".into()),
            Stmt::Comment("target-adjacent comment".into()),
            Stmt::Return(None),
            Stmt::Try {
                try_body: vec![],
                catches: vec![],
                finally_body: Some(vec![Stmt::Goto("Lfinally".into())]),
            },
            Stmt::Label("Lfinally".into()),
            Stmt::Return(None),
        ];
        fold_gotos_to_return(&mut stmts);
        assert_eq!(
            count_gotos(&stmts),
            1,
            "only finally source remains: {stmts:?}"
        );
        let Stmt::If { then_body, .. } = &stmts[0] else {
            panic!("missing if");
        };
        assert!(matches!(then_body.as_slice(), [Stmt::Return(None)]));
        let Stmt::While { body, .. } = &stmts[1] else {
            panic!("missing while");
        };
        assert!(matches!(body.as_slice(), [Stmt::Return(None)]));
        let Stmt::Try {
            finally_body: Some(body),
            ..
        } = &stmts[5]
        else {
            panic!("missing finally");
        };
        assert!(matches!(body.as_slice(), [Stmt::Goto(label)] if label == "Lfinally"));
    }

    #[test]
    fn goto_to_immediate_loop_and_switch_continuations_becomes_break() {
        let mut loop_stmts = vec![
            Stmt::While {
                cond: var("loop"),
                body: vec![Stmt::If {
                    cond: var("exit"),
                    then_body: vec![Stmt::Goto("Lafter_loop".into())],
                    else_body: vec![],
                }],
            },
            Stmt::Comment("continuation anchor".into()),
            Stmt::Label("Lafter_loop".into()),
            Stmt::Eval(var("after")),
        ];
        fold_gotos_to_break(&mut loop_stmts);
        assert_eq!(
            count_gotos(&loop_stmts),
            0,
            "loop continuation goto remains: {loop_stmts:?}"
        );
        assert!(render_stmts(&loop_stmts).contains("break;"));

        let mut switch_stmts = vec![
            Stmt::Switch {
                disc: "selector".into(),
                cases: vec![(0, vec![Stmt::Goto("Lafter_switch".into())])],
                tail: vec![],
            
                default: None,},
            Stmt::Label("Lafter_switch".into()),
            Stmt::Return(None),
        ];
        fold_gotos_to_break(&mut switch_stmts);
        assert_eq!(
            count_gotos(&switch_stmts),
            0,
            "switch continuation goto remains: {switch_stmts:?}"
        );
        assert!(render_stmts(&switch_stmts).contains("break;"));
    }

    #[test]
    fn shared_if_suffix_is_hoisted_after_both_arms() {
        let mut stmts = vec![Stmt::If {
            cond: var("condition"),
            then_body: vec![
                Stmt::Eval(var("then_prefix")),
                Stmt::Label("Lshared".into()),
                Stmt::Eval(var("shared_effect")),
                Stmt::Return(None),
            ],
            else_body: vec![Stmt::Eval(var("else_prefix")), Stmt::Goto("Lshared".into())],
        }];
        fold_shared_if_suffixes(&mut stmts);
        let Stmt::If {
            then_body,
            else_body,
            ..
        } = &stmts[0]
        else {
            panic!("if lost");
        };
        assert!(matches!(then_body.as_slice(), [Stmt::Eval(_)]));
        assert!(matches!(else_body.as_slice(), [Stmt::Eval(_)]));
        assert!(matches!(
            stmts.as_slice(),
            [Stmt::If { .. }, Stmt::Label(label), Stmt::Eval(_), Stmt::Return(None)]
                if label == "Lshared"
        ));
        assert_eq!(count_gotos(&stmts), 0);
    }

    #[test]
    fn shared_if_suffix_refuses_declarations_and_preserves_external_label_refs() {
        let declaration = vec![Stmt::If {
            cond: var("condition"),
            then_body: vec![
                Stmt::Label("Lshared".into()),
                Stmt::Assign("local".into(), Some("int".into()), var("value")),
            ],
            else_body: vec![Stmt::Goto("Lshared".into())],
        }];
        let mut declaration = declaration;
        fold_shared_if_suffixes(&mut declaration);
        assert_eq!(
            count_gotos(&declaration),
            1,
            "declaration scope was moved: {declaration:?}"
        );

        let mut external_ref = vec![
            Stmt::If {
                cond: var("condition"),
                then_body: vec![Stmt::Label("Lshared".into()), Stmt::Eval(var("effect"))],
                else_body: vec![Stmt::Goto("Lshared".into())],
            },
            Stmt::Goto("Lshared".into()),
        ];
        fold_shared_if_suffixes(&mut external_ref);
        assert_eq!(
            count_gotos(&external_ref),
            1,
            "the arm continuation goto should fold: {external_ref:?}"
        );
        assert!(
            matches!(
                external_ref.as_slice(),
                [Stmt::If { .. }, Stmt::Label(label), Stmt::Eval(_), Stmt::Goto(target)]
                    if label == "Lshared" && target == "Lshared"
            ),
            "external goto must retain its target after hoisting: {external_ref:?}"
        );
    }

    #[test]
    fn goto_to_outer_loop_continuation_refuses_nested_breakable_and_finally_sources() {
        let mut stmts = vec![
            Stmt::While {
                cond: var("outer"),
                body: vec![
                    Stmt::Switch {
                        disc: "selector".into(),
                        cases: vec![(0, vec![Stmt::Goto("Lafter_outer".into())])],
                        tail: vec![],
                    
                        default: None,},
                    Stmt::Try {
                        try_body: vec![],
                        catches: vec![],
                        finally_body: Some(vec![Stmt::Goto("Lafter_outer".into())]),
                    },
                ],
            },
            Stmt::Label("Lafter_outer".into()),
            Stmt::Return(None),
        ];
        fold_gotos_to_break(&mut stmts);
        assert_eq!(
            count_gotos(&stmts),
            2,
            "outer-scope or finally goto was folded: {stmts:?}"
        );
        assert!(!render_stmts(&stmts).contains("break;"));
    }

    /// A 2-guard chain with a prelude between the guards must fold FULLY.
    ///
    /// `[G1, B1, G2, B2, J:]` with no flat labels is two nested guards, not
    /// two jumps. Forward order folded G1 first and stranded G2 cross-level
    /// (1 goto left); reverse folds G2 first and then G1 (0 gotos).
    #[test]
    fn guard_chain_with_prelude_folds_fully() {
        let mut stmts = vec![
            guard("c1", "J"),
            Stmt::Eval(var("prelude")),
            guard("c2", "J"),
            Stmt::Eval(var("body")),
            Stmt::Label("J".into()),
            Stmt::Return(None),
        ];
        branch_repair(&mut stmts);
        assert_eq!(
            count_gotos(&stmts),
            0,
            "both guards must fold to nested `if (!c)` shells, got: {stmts:?}"
        );
        // The predicates survive (inverted), the bodies survive nested.
        let Stmt::If {
            cond, then_body, ..
        } = &stmts[0]
        else {
            panic!("outer guard did not fold to an if head: {stmts:?}");
        };
        assert!(
            matches!(cond, Expr::Not(_)),
            "outer predicate not inverted: {cond:?}"
        );
        assert!(
            then_body.iter().any(|s| matches!(s, Stmt::Eval(_))),
            "prelude lost in the fold: {stmts:?}"
        );
    }

    /// A flat label between the guard and its join blocks the fold when an edge
    /// from OUTSIDE the region targets it (that edge would become conditional
    /// under `!c`). Regression pin for 0x2CA7AC: the `v100 != 0` guard's region
    /// holds `L14:`, landed on from across the method — and a prior flat-gating
    /// variant deleted the guard itself here instead of keeping it.
    #[test]
    fn flat_label_still_blocks_the_fold() {
        let mut stmts = vec![
            guard("v100", "L3"),
            Stmt::Eval(var("cleanup")),
            Stmt::Label("L14".into()),
            Stmt::Eval(var("tail")),
            Stmt::Label("L3".into()),
            // The outside edge: in the real method many `goto L14` land here
            // from beyond this guard's region.
            Stmt::Goto("L14".into()),
            Stmt::Return(None),
        ];
        branch_repair(&mut stmts);
        assert_eq!(
            count_gotos(&stmts),
            2,
            "the guard goto and the outside edge must both survive: {stmts:?}"
        );
        let out = render_stmts(&stmts);
        assert!(
            out.contains("v100"),
            "the guard condition must survive (a prior variant deleted it):\n{out}"
        );
        assert!(
            out.contains("L14:"),
            "the outside landing site must survive:\n{out}"
        );
    }

    /// A guard whose region holds a flat label NOTHING targets must still fold.
    ///
    /// The label is a dead merge anchor: no edge in the whole method reaches
    /// it, and `strip_quiet_labels` removes it right after this fold. Refusing
    /// on it left real guard chains half-structured (one `goto` per dead
    /// anchor), while folding moves nothing observable — the predicate is
    /// inverted, never deleted, and the region moves verbatim.
    #[test]
    fn guard_with_dead_interior_label_folds_fully() {
        let mut stmts = vec![
            guard("c1", "J"),
            Stmt::Eval(var("prelude")),
            Stmt::Label("Ldead".into()),
            Stmt::Eval(var("body")),
            Stmt::Label("J".into()),
            Stmt::Return(None),
        ];
        branch_repair(&mut stmts);
        assert_eq!(
            count_gotos(&stmts),
            0,
            "a dead anchor must not block the fold, got: {stmts:?}"
        );
        let Stmt::If {
            cond, then_body, ..
        } = &stmts[0]
        else {
            panic!("outer guard did not fold to an if head: {stmts:?}");
        };
        assert!(
            matches!(cond, Expr::Not(_)),
            "outer predicate not inverted: {cond:?}"
        );
        assert!(
            then_body.iter().any(|s| matches!(s, Stmt::Eval(_))),
            "prelude/body lost in the fold: {stmts:?}"
        );
        let out = render_stmts(&stmts);
        assert!(
            out.contains("c1"),
            "the guard condition must survive (inverted), got:\n{out}"
        );
    }

    #[test]
    fn flat_guard_body_nesting_refuses_scope_changes_and_labels() {
        let safe_body = vec![
            Stmt::Eval(var("side_effect")),
            Stmt::Assign("v1".into(), None, var("value")),
        ];
        assert_eq!(flat_guard_body_nesting_refusal(&safe_body, 0, false), None);
        assert_eq!(
            flat_guard_body_nesting_refusal(
                &[Stmt::Assign("v1".into(), Some("int".into()), var("value"))],
                0,
                false,
            ),
            Some(FlatGuardNestingRefusal::Declaration)
        );
        assert_eq!(
            flat_guard_body_nesting_refusal(&[Stmt::Label("L1".into())], 0, false),
            Some(FlatGuardNestingRefusal::Label)
        );
        let nested = vec![Stmt::If {
            cond: var("c"),
            then_body: vec![Stmt::Eval(var("x"))],
            else_body: vec![],
        }];
        assert_eq!(
            flat_guard_body_nesting_refusal(&nested, MAX_NEST_DEPTH, false),
            Some(FlatGuardNestingRefusal::Depth)
        );
        let replacement =
            flat_guard_replacement(&var("condition"), &[Stmt::Eval(var("body"))], 0, false)
                .expect("safe guard gets structured");
        let Stmt::If {
            cond: Expr::Not(inner),
            then_body,
            else_body,
        } = replacement
        else {
            panic!("flat guard did not become an inverted if");
        };
        assert!(matches!(*inner, Expr::Var(ref name) if name == "condition"));
        assert_eq!(then_body.len(), 1);
        assert!(else_body.is_empty());
        assert!(
            flat_guard_replacement(&var("condition"), &[Stmt::Label("L1".into())], 0, false,)
                .is_none()
        );
    }

    #[test]
    fn flat_guard_allows_labels_with_only_fall_arm_predecessors() {
        let sc = StructuredCfg {
            blocks: vec![
                BlockInfo {
                    start: 0,
                    end: 1,
                    succ_taken: Some(2),
                    succ_fall: Some(1),
                },
                BlockInfo {
                    start: 1,
                    end: 2,
                    succ_taken: None,
                    succ_fall: None,
                },
                BlockInfo {
                    start: 2,
                    end: 3,
                    succ_taken: None,
                    succ_fall: None,
                },
            ],
            block_of: vec![],
            full_succ: vec![vec![1], vec![], vec![]],
            labels: HashMap::from([(1, "L0".into())]),
            label_names: HashSet::from(["L0".into()]),
            idom: vec![None; 3],
            ipdom: vec![None; 3],
            preds: vec![vec![], vec![0], vec![]],
        };
        let body = vec![Stmt::Label("L0".into()), Stmt::Eval(var("inside"))];
        let fall_blocks = HashSet::from([1]);
        assert!(flat_guard_labels_are_internal(&sc, &body, &fall_blocks, 0));
        assert!(flat_guard_replacement(&var("condition"), &body, 0, true).is_some());

        let mut with_outside_edge = sc;
        with_outside_edge.full_succ[2].push(1);
        assert!(!flat_guard_labels_are_internal(
            &with_outside_edge,
            &body,
            &fall_blocks,
            0,
        ));
        assert!(flat_guard_replacement(&var("condition"), &body, 0, false).is_none());

        let mut with_taken_edge = with_outside_edge;
        with_taken_edge.full_succ[2].clear();
        with_taken_edge.blocks[0].succ_taken = Some(1);
        with_taken_edge.full_succ[0] = vec![1];
        assert!(!flat_guard_labels_are_internal(
            &with_taken_edge,
            &body,
            &fall_blocks,
            0,
        ));
    }

    /// A guard whose region holds a label reached ONLY from inside the region
    /// must still fold: the landing site and its edges move together under the
    /// inverted predicate, so no outside edge can become conditional.
    #[test]
    fn guard_with_inside_only_interior_label_folds() {
        let mut stmts = vec![
            guard("c1", "J"),
            Stmt::Goto("Linner".into()),
            Stmt::Eval(var("skipped")),
            Stmt::Label("Linner".into()),
            Stmt::Eval(var("body")),
            Stmt::Label("J".into()),
            Stmt::Return(None),
        ];
        branch_repair(&mut stmts);
        assert_eq!(
            count_gotos(&stmts),
            1,
            "only the interior jump may remain, got: {stmts:?}"
        );
        let out = render_stmts(&stmts);
        assert!(
            out.contains("c1"),
            "the guard condition must survive (inverted), got:\n{out}"
        );
        assert!(
            out.contains("Linner:"),
            "the interior landing site must survive with its edge, got:\n{out}"
        );
    }

    /// A NESTED label reached from outside the region blocks the fold too.
    ///
    /// Pulling the region under `!c` makes every landing site inside it
    /// conditional — a label nested in an arm is no more opaque than a flat
    /// one. A flat-only gate folds here and strands the outside edge; the
    /// all-depths gate keeps the guard exactly as emitted.
    #[test]
    fn guard_with_nested_outside_edge_refuses() {
        let mut stmts = vec![
            guard("c1", "J"),
            Stmt::If {
                cond: var("d"),
                then_body: vec![Stmt::Label("Lnested".into()), Stmt::Eval(var("x"))],
                else_body: vec![],
            },
            Stmt::Eval(var("body")),
            Stmt::Label("J".into()),
            Stmt::Goto("Lnested".into()),
            Stmt::Return(None),
        ];
        branch_repair(&mut stmts);
        assert_eq!(
            count_gotos(&stmts),
            2,
            "the guard goto and the outside edge to the nested label must both survive: {stmts:?}"
        );
        let out = render_stmts(&stmts);
        assert!(
            out.contains("c1"),
            "the guard condition must survive, got:\n{out}"
        );
        assert!(
            out.contains("Lnested:"),
            "the nested landing site must survive, got:\n{out}"
        );
    }

    /// A NESTED label reached only from inside the region folds with it.
    ///
    /// The landing site and its edge move together under the inverted
    /// predicate, so no outside edge can become conditional. Guards the
    /// all-depths gate against over-blocking: nested self-contained labels
    /// must fold exactly like flat ones.
    #[test]
    fn guard_with_nested_inside_only_label_folds() {
        let mut stmts = vec![
            guard("c1", "J"),
            Stmt::If {
                cond: var("d"),
                then_body: vec![
                    Stmt::Goto("Lnested".into()),
                    Stmt::Eval(var("skipped")),
                    Stmt::Label("Lnested".into()),
                ],
                else_body: vec![],
            },
            Stmt::Eval(var("body")),
            Stmt::Label("J".into()),
            Stmt::Return(None),
        ];
        branch_repair(&mut stmts);
        assert_eq!(
            count_gotos(&stmts),
            1,
            "only the interior jump may remain, got: {stmts:?}"
        );
        let out = render_stmts(&stmts);
        assert!(
            out.contains("c1"),
            "the guard condition must survive (inverted), got:\n{out}"
        );
        assert!(
            out.contains("Lnested:"),
            "the nested landing site must survive with its edge, got:\n{out}"
        );
    }

    /// Regression pin for 0x1FE8D94: a switch whose arms each hold a guard to
    /// a shared tail. A third-arm-merge variant once dropped 16 conditions —
    /// this fold never merges arms: each arm folds (or keeps) its own guard
    /// with its own predicate, and every condition reaches the text.
    #[test]
    fn switch_arms_keep_their_own_guards() {
        let arm = |c: &str, b: &str, t: &str| {
            vec![guard(c, t), Stmt::Eval(var(b)), Stmt::Label(t.into())]
        };
        let mut stmts = vec![Stmt::Switch {
            disc: "v".into(),
            cases: vec![
                (0, arm("c0", "b0", "T0")),
                (1, arm("c1", "b1", "T1")),
                (2, arm("c2", "b2", "T2")),
            ],
            tail: vec![Stmt::Label("Tshared".into())],
        
            default: None,}];
        branch_repair(&mut stmts);
        let Stmt::Switch { cases, .. } = &stmts[0] else {
            panic!("the switch shell must survive, got: {stmts:?}");
        };
        assert_eq!(cases.len(), 3, "arms must never merge, got: {stmts:?}");
        let out = render_stmts(&stmts);
        for c in ["c0", "c1", "c2"] {
            assert!(
                out.contains(c),
                "arm condition {c} lost (a prior variant dropped 16), got:\n{out}"
            );
        }
        assert_eq!(
            count_gotos(&stmts),
            0,
            "each arm guard folds inside its own arm, got: {stmts:?}"
        );
    }

    /// A guard nested under an enclosing guard that already establishes its
    /// predicate must keep its LIVE arm, not its dead one.
    ///
    /// Regression pin for 0x1EB2F30: `apply_known` answered a `Ne` query
    /// against an established `Ne` fact with `false` (the `Eq` answer), so
    /// `fold_decided_guards` took the else-arm of a nested same-polarity
    /// guard and deleted the live then-arm — a 32-line copy loop vanished
    /// once the guard-chain fold nested it under its superset check.
    /// Predicates are inverted, never deleted; arms are kept.
    #[test]
    fn decided_guard_keeps_the_live_arm() {
        let ne0 = |v: &str| Expr::Cmp(CmpKind::Ne, Box::new(var(v)), Box::new(Expr::Int(0)));
        let mut stmts = vec![Stmt::If {
            cond: ne0("v125"),
            then_body: vec![Stmt::If {
                cond: ne0("v125"),
                then_body: vec![Stmt::Eval(var("live"))],
                else_body: vec![],
            }],
            else_body: vec![],
        }];
        fold_decided_guards(&mut stmts);
        let out = render_stmts(&stmts);
        assert!(
            out.contains("live"),
            "the live arm was deleted as if dead, got:\n{out}"
        );
        assert!(
            out.contains("v125"),
            "the predicate must survive, got:\n{out}"
        );
    }

    /// A jump from one case body to another case entry is expressible without
    /// a method-level label. The rewrite is limited to the enclosing switch.
    #[test]
    fn switch_case_entry_goto_uses_goto_case() {
        let mut stmts = vec![Stmt::Switch {
            disc: "selector".into(),
            cases: vec![
                (
                    0,
                    vec![Stmt::Label("Lcase1".into()), Stmt::Goto("Lcase2".into())],
                ),
                (1, vec![Stmt::Label("Lcase2".into()), Stmt::Return(None)]),
            ],
            tail: vec![Stmt::Label("Loutside".into())],
        
            default: None,}];
        branch_repair(&mut stmts);
        let out = render_stmts(&stmts);
        assert!(
            out.contains("goto case 1;"),
            "case jump was not lowered:\n{out}"
        );
        assert!(
            !out.contains("goto Lcase2;"),
            "old label jump remains:\n{out}"
        );
        assert!(out.contains("return;"), "target arm was lost:\n{out}");
    }
}

#[cfg(test)]
mod array_init_tests {
    use super::*;

    fn render_expr(e: &Expr) -> String {
        let mut out = String::new();
        e.render(&mut out);
        out
    }

    #[test]
    fn render_basic_array_init() {
        let e = Expr::ArrayInit {
            elem_type: "int".into(),
            items: vec![Expr::Int(1), Expr::Int(2), Expr::Int(3)],
        };
        let out = render_expr(&e);
        assert_eq!(out, "new int[] { 1, 2, 3 }");
    }

    #[test]
    fn render_empty_array_init() {
        let e = Expr::ArrayInit {
            elem_type: "string".into(),
            items: vec![],
        };
        let out = render_expr(&e);
        assert_eq!(out, "new string[] {}");
    }

    #[test]
    fn render_array_init_with_complex_items() {
        let e = Expr::ArrayInit {
            elem_type: "float".into(),
            items: vec![
                Expr::Float(1.0),
                Expr::Bin(BinOp::Add, Box::new(Expr::Var("x".into())), Box::new(Expr::Int(1))),
            ],
        };
        let out = render_expr(&e);
        assert_eq!(out, "new float[] { 1f, x + 1 }");
    }

    #[test]
    fn precedence_is_leaf() {
        let e = Expr::ArrayInit {
            elem_type: "int".into(),
            items: vec![Expr::Int(1)],
        };
        assert_eq!(e.precedence(), 15);
    }

    #[test]
    fn structural_equal() {
        let a = Expr::ArrayInit {
            elem_type: "int".into(),
            items: vec![Expr::Int(1), Expr::Int(2)],
        };
        let b = Expr::ArrayInit {
            elem_type: "int".into(),
            items: vec![Expr::Int(1), Expr::Int(2)],
        };
        assert!(exprs_eq(&a, &b));
    }

    #[test]
    fn structural_not_equal_different_type() {
        let a = Expr::ArrayInit {
            elem_type: "int".into(),
            items: vec![Expr::Int(1)],
        };
        let b = Expr::ArrayInit {
            elem_type: "float".into(),
            items: vec![Expr::Int(1)],
        };
        assert!(!exprs_eq(&a, &b));
    }

    #[test]
    fn structural_not_equal_different_items() {
        let a = Expr::ArrayInit {
            elem_type: "int".into(),
            items: vec![Expr::Int(1), Expr::Int(2)],
        };
        let b = Expr::ArrayInit {
            elem_type: "int".into(),
            items: vec![Expr::Int(1), Expr::Int(3)],
        };
        assert!(!exprs_eq(&a, &b));
    }

    #[test]
    fn expr_has_call_true_when_item_has_call() {
        let e = Expr::ArrayInit {
            elem_type: "int".into(),
            items: vec![
                Expr::Int(1),
                Expr::Call {
                    recv: None,
                    name: "Foo".into(),
                    args: vec![],
                },
            ],
        };
        assert!(expr_has_call(&e));
    }

    #[test]
    fn expr_has_call_false_for_pure_items() {
        let e = Expr::ArrayInit {
            elem_type: "int".into(),
            items: vec![Expr::Int(1), Expr::Int(2)],
        };
        assert!(!expr_has_call(&e));
    }

    #[test]
    fn expr_effectful_when_item_effectful() {
        let e = Expr::ArrayInit {
            elem_type: "object".into(),
            items: vec![Expr::NewObj("List".into(), vec![])],
        };
        assert!(expr_effectful(&e));
    }

    #[test]
    fn expr_not_effectful_for_pure_items() {
        let e = Expr::ArrayInit {
            elem_type: "int".into(),
            items: vec![Expr::Int(1), Expr::Int(2)],
        };
        assert!(!expr_effectful(&e));
    }

    #[test]
    fn collect_used_vars_from_items() {
        let e = Expr::ArrayInit {
            elem_type: "int".into(),
            items: vec![Expr::Var("x".into()), Expr::Var("y".into())],
        };
        let mut vars = HashSet::new();
        collect_used_vars(&e, &mut vars);
        assert!(vars.contains("x"));
        assert!(vars.contains("y"));
        assert_eq!(vars.len(), 2);
    }

    // -----------------------------------------------------------------------
    // Lambda body production tests (Phase 5A)
    // -----------------------------------------------------------------------

    /// `is_lambda_method` matches the compiler-generated lambda pattern.
    #[test]
    fn is_lambda_method_detects_generated_names() {
        assert!(is_lambda_method("<>c.<M>b__1_0"));
        assert!(is_lambda_method("<>c.<Method>b__0"));
        assert!(is_lambda_method(
            "<MyClass>o__DisplayClass3.<Method>b__0"
        ));
        assert!(is_lambda_method("<>c__DisplayClass5.<M>b__1"));
    }

    /// `is_lambda_method` rejects ordinary method names.
    #[test]
    fn is_lambda_method_rejects_ordinary_names() {
        assert!(!is_lambda_method("MyClass.MyMethod"));
        assert!(!is_lambda_method("Update"));
        assert!(!is_lambda_method("<>c..cctor"));
        assert!(!is_lambda_method("<>c.ToString"));
        assert!(!is_lambda_method(""));
    }

    /// `extract_lambda_body` accepts a single return statement.
    #[test]
    fn extract_lambda_body_accepts_single_return() {
        let expr = Expr::Field(Box::new(Expr::Var("x".into())), "Value".into());
        let stmts = vec![Stmt::Return(Some(expr.clone()))];
        let result = extract_lambda_body(&stmts);
        assert!(result.is_some(), "a single return must extract");
        assert!(matches!(result.unwrap(), Expr::Field(..)));
    }

    /// `extract_lambda_body` accepts a single eval statement (void lambda).
    #[test]
    fn extract_lambda_body_accepts_single_eval() {
        let expr = Expr::Call {
            recv: None,
            name: "DoSomething".into(),
            args: vec![Expr::Var("x".into())],
        };
        let stmts = vec![Stmt::Eval(expr)];
        assert!(extract_lambda_body(&stmts).is_some());
    }

    /// `extract_lambda_body` rejects multi-statement bodies.
    #[test]
    fn extract_lambda_body_rejects_multi_statement() {
        let stmts = vec![
            Stmt::Eval(Expr::Var("setup".into())),
            Stmt::Return(Some(Expr::Var("x".into()))),
        ];
        assert!(
            extract_lambda_body(&stmts).is_none(),
            "multi-statement bodies must not extract"
        );
    }

    /// `extract_lambda_body` rejects a bare return (no expression).
    #[test]
    fn extract_lambda_body_rejects_bare_return() {
        let stmts = vec![Stmt::Return(None)];
        assert!(extract_lambda_body(&stmts).is_none());
    }

    /// `extract_lambda_body` rejects an empty body.
    #[test]
    fn extract_lambda_body_rejects_empty_body() {
        let stmts: Vec<Stmt> = vec![];
        assert!(extract_lambda_body(&stmts).is_none());
    }

    /// The global registration and lookup round-trips correctly.
    #[test]
    fn lambda_body_registration_round_trips() {
        clear_lambda_bodies();
        let body = Expr::Var("x".into());
        register_lambda_body(
            "<>c.<M>b__1_0".to_string(),
            vec!["x".to_string()],
            body.clone(),
        );
        let result = lookup_lambda_body("<>c.<M>b__1_0");
        assert!(result.is_some(), "registered body must be found");
        let (params, expr) = result.unwrap();
        assert_eq!(params, vec!["x".to_string()]);
        assert!(matches!(expr, Expr::Var(ref v) if v == "x"));
        // An unregistered name returns None.
        assert!(lookup_lambda_body("<>c.<Other>b__2_0").is_none());
        clear_lambda_bodies();
    }

    /// `inject_lambda_bodies` prepends synthetic Assign statements for
    /// delegate constructions that reference registered lambdas.
    #[test]
    fn inject_lambda_bodies_prepends_synthetic_bindings() {
        clear_lambda_bodies();
        // Register a lambda body.
        let body = Expr::Field(Box::new(Expr::Var("x".into())), "Value".into());
        register_lambda_body(
            "<>c.<M>b__1_0".to_string(),
            vec!["x".to_string()],
            body,
        );
        // Build a statement list with a delegate construction referencing it.
        let mut stmts = vec![Stmt::Assign(
            "action".to_string(),
            None,
            Expr::Call {
                recv: None,
                name: "System.Action`1..ctor".into(),
                args: vec![
                    Expr::This,
                    Expr::MethodGroup("<>c.<M>b__1_0".to_string()),
                ],
            },
        )];
        inject_lambda_bodies(&mut stmts);
        // The synthetic binding must be prepended.
        assert!(
            stmts.len() == 2,
            "expected 2 statements (injected + original), got {}",
            stmts.len()
        );
        assert!(
            matches!(&stmts[0], Stmt::Assign(name, None, Expr::Lambda { .. }) if name == "<>c.<M>b__1_0"),
            "first statement must be the injected lambda binding, got: {:?}",
            stmts[0]
        );
        clear_lambda_bodies();
    }

    /// `inject_lambda_bodies` is a no-op when no lambdas are referenced.
    #[test]
    fn inject_lambda_bodies_is_noop_without_references() {
        clear_lambda_bodies();
        let mut stmts = vec![Stmt::Return(Some(Expr::Var("x".into())))];
        inject_lambda_bodies(&mut stmts);
        assert_eq!(stmts.len(), 1, "no injection expected");
        clear_lambda_bodies();
    }

    /// End-to-end integration: register a lambda body, inject it into a
    /// statement list with a delegate construction, then run closures::apply
    /// and verify the construction folds to Expr::Lambda.
    #[test]
    fn end_to_end_lambda_body_production_and_closure_folding() {
        clear_lambda_bodies();
        // Step 1: Simulate the renderer processing a lambda method.
        let lambda_body = Expr::Field(Box::new(Expr::Var("x".into())), "Value".into());
        register_lambda_body(
            "<>c.<M>b__1_0".to_string(),
            vec!["x".to_string()],
            lambda_body,
        );
        // Step 2: Build a statement list with a delegate construction.
        let mut stmts = vec![
            Stmt::Assign(
                "action".to_string(),
                None,
                Expr::Call {
                    recv: None,
                    name: "System.Action`1..ctor".into(),
                    args: vec![
                        Expr::This,
                        Expr::MethodGroup("<>c.<M>b__1_0".to_string()),
                    ],
                },
            ),
        ];
        // Step 3: Inject lambda bodies (what render_method_csharp_full_chains does).
        inject_lambda_bodies(&mut stmts);
        assert_eq!(stmts.len(), 2, "injected binding + original");
        // Step 4: Run closures::apply (what reconstruct::apply does).
        let n = super::super::reconstruct::closures::apply(&mut stmts);
        assert_eq!(n, 1, "the delegate construction must fold to a lambda");
        // Step 5: Verify the result is an Expr::Lambda.
        match &stmts[1] {
            Stmt::Assign(_, _, Expr::Lambda { params, body }) => {
                assert_eq!(params.len(), 1);
                assert_eq!(params[0], "x");
                assert!(matches!(body.as_ref(), Expr::Field(..)));
            }
            other => panic!("expected folded lambda, got: {other:?}"),
        }
        clear_lambda_bodies();
    }
}

// ---------------------------------------------------------------------------
// Base-call reconstruction tests (Phase 5B)
// ---------------------------------------------------------------------------
//
// The rewrite lives in `call_parts`: when the callee's declaring type is a
// STRICT ANCESTOR of the current method's declaring type AND the receiver is
// `this`, the receiver is rewritten to `base`. These tests exercise the
// detection through `MethodCtx::call_parts` with synthetic parent chains.
#[cfg(test)]
mod base_call_tests {
    use super::*;
    use crate::recovery::ir::{Insn, Op, Operand};
    use crate::recovery::locals::{LocalInfo, LocalTable};
    use crate::recovery::types::{ManagedType, MethodRef, MethodSigInfo};
    use std::collections::HashMap;

    /// Build a minimal `MethodCtx` with the given declaring TDI and parent chain.
    fn ctx_with_chain<'a>(
        insns: &'a [Insn],
        table: &'a LocalTable,
        declaring_tdi: i32,
        parent_chain: &'a HashMap<i32, Vec<i32>>,
    ) -> MethodCtx<'a> {
        MethodCtx::build(insns, table, declaring_tdi, parent_chain, false, None)
    }

    /// Build a `LocalTable` with a `this` local (version 0) and optionally
    /// extra locals.
    fn this_table(extra: &[(u32, &str)]) -> LocalTable {
        let mut t = LocalTable::default();
        // version 0 = this
        t.infos.push(LocalInfo {
            slot_origin: "x0".into(),
            ty: ManagedType::Object,
            is_this: true,
            is_param: None,
            param_comp: None,
            is_return_buffer: false,
            is_incoming_arg: false,
            is_call_clobber: false,
        });
        t.index_of.insert(0, 0);
        for (v, origin) in extra {
            let idx = t.infos.len();
            t.infos.push(LocalInfo {
                slot_origin: origin.to_string(),
                ty: ManagedType::Object,
                is_this: false,
                is_param: None,
                param_comp: None,
                is_return_buffer: false,
                is_incoming_arg: false,
                is_call_clobber: false,
            });
            t.index_of.insert(*v, idx);
        }
        t
    }

    /// Build a `MethodRef` for an instance method on the given TDI.
    fn instance_mref(name: &str, tdi: i32) -> MethodRef {
        MethodRef {
            image_index: 0,
            type_def_index: tdi,
            method_index: 0,
            name: name.into(),
            declaring_namespace: "Test".into(),
            declaring_type_name: format!("Type{tdi}"),
            assembly: String::new(),
            sig: MethodSigInfo {
                ret: ManagedType::Primitive(crate::recovery::types::PrimKind::Void),
                params: vec![],
                is_static: false,
            },
        }
    }

    /// Build a `MethodRef` for a static method on the given TDI.
    fn static_mref(name: &str, tdi: i32) -> MethodRef {
        MethodRef {
            image_index: 0,
            type_def_index: tdi,
            method_index: 0,
            name: name.into(),
            declaring_namespace: "Test".into(),
            declaring_type_name: format!("Type{tdi}"),
            assembly: String::new(),
            sig: MethodSigInfo {
                ret: ManagedType::Primitive(crate::recovery::types::PrimKind::Void),
                params: vec![],
                is_static: true,
            },
        }
    }

    /// Build an `Op::Call` instruction with the given method and receiver local.
    fn call_insn(m: MethodRef, recv_local: u32) -> Insn {
        Insn::new(
            Op::Call,
            vec![
                Operand::Method(m),
                Operand::Unknown, // retv slot
                Operand::Local(recv_local),
            ],
            0x1000,
        )
    }

    /// `is_strict_ancestor` returns true for a type in the parent chain that is
    /// NOT the declaring type itself.
    #[test]
    fn is_strict_ancestor_excludes_self() {
        // Chain: Type10 -> [10, 20, 30] (self first)
        let mut chain = HashMap::new();
        chain.insert(10, vec![10, 20, 30]);
        let table = this_table(&[]);
        let insns = vec![Insn::new(Op::Nop, vec![], 0x1000)];
        let ctx = ctx_with_chain(&insns, &table, 10, &chain);

        assert!(!ctx.is_strict_ancestor(10), "self is not a strict ancestor");
        assert!(ctx.is_strict_ancestor(20), "parent should be a strict ancestor");
        assert!(ctx.is_strict_ancestor(30), "grandparent should be a strict ancestor");
        assert!(!ctx.is_strict_ancestor(99), "unrelated type is not an ancestor");
    }

    /// `is_strict_ancestor` returns false when the parent chain is empty.
    #[test]
    fn is_strict_ancestor_false_with_empty_chain() {
        let chain = HashMap::new();
        let table = this_table(&[]);
        let insns = vec![Insn::new(Op::Nop, vec![], 0x1000)];
        let ctx = ctx_with_chain(&insns, &table, 10, &chain);

        assert!(!ctx.is_strict_ancestor(20), "no chain means no ancestor");
    }

    /// Instance call on a strict ancestor with `this` receiver → `base.Method()`.
    #[test]
    fn base_call_rewrite_on_strict_ancestor() {
        // Declaring type: TDI 10, parent chain: [10, 20]
        // Callee: instance method "OnEnter" declared on TDI 20 (the parent)
        let mut chain = HashMap::new();
        chain.insert(10, vec![10, 20]);
        let table = this_table(&[]);
        let m = instance_mref("OnEnter", 20);
        let insns = vec![call_insn(m, 0)]; // receiver is local 0 (this)
        let ctx = ctx_with_chain(&insns, &table, 10, &chain);

        let (recv, name, args) = ctx.call_parts(0, 0).expect("call_parts should succeed");
        assert!(
            matches!(recv.as_deref(), Some(Expr::Var(n)) if n == "base"),
            "receiver should be rewritten to `base`, got {recv:?}"
        );
        assert_eq!(name, "OnEnter");
        assert!(args.is_empty(), "no extra params in this test");
    }

    /// Instance call on the SAME type is NOT a base call — stays `this.Method()`.
    #[test]
    fn same_type_call_is_not_a_base_call() {
        let mut chain = HashMap::new();
        chain.insert(10, vec![10, 20]);
        let table = this_table(&[]);
        let m = instance_mref("DoStuff", 10); // same declaring type
        let insns = vec![call_insn(m, 0)];
        let ctx = ctx_with_chain(&insns, &table, 10, &chain);

        let (recv, name, _) = ctx.call_parts(0, 0).expect("call_parts should succeed");
        // Receiver should remain `this`, not `base`
        assert!(
            matches!(recv.as_deref(), Some(Expr::Var(n)) if n == "this"),
            "same-type call should keep `this` receiver, got {recv:?}"
        );
        assert_eq!(name, "DoStuff");
    }

    /// Static calls are never rewritten, even if the TDI is an ancestor.
    #[test]
    fn static_call_is_never_a_base_call() {
        let mut chain = HashMap::new();
        chain.insert(10, vec![10, 20]);
        let table = this_table(&[]);
        let m = static_mref("Helper", 20); // static on ancestor
        let insns = vec![call_insn(m, 0)];
        let ctx = ctx_with_chain(&insns, &table, 10, &chain);

        let (recv, name, _) = ctx.call_parts(0, 0).expect("call_parts should succeed");
        // Static calls have no receiver
        assert!(recv.is_none(), "static call should have no receiver, got {recv:?}");
        // Name should be qualified: "Type20.Helper"
        assert!(name.contains("Helper"), "name should contain the method name");
    }

    /// Call with a non-`this` receiver is NOT rewritten, even on an ancestor.
    #[test]
    fn foreign_receiver_is_not_a_base_call() {
        let mut chain = HashMap::new();
        chain.insert(10, vec![10, 20]);
        // Local 5 is NOT `this`
        let table = this_table(&[(5, "x1")]);
        let m = instance_mref("OnEnter", 20);
        let insns = vec![call_insn(m, 5)]; // receiver is local 5, not this
        let ctx = ctx_with_chain(&insns, &table, 10, &chain);

        let (recv, _, _) = ctx.call_parts(0, 0).expect("call_parts should succeed");
        // Receiver should NOT be `base` — it's some other object
        assert!(
            !matches!(recv.as_deref(), Some(Expr::Var(n)) if n == "base"),
            "non-this receiver should not become `base`, got {recv:?}"
        );
    }

    /// Multiple inheritance levels: grandparent call is also a base call.
    #[test]
    fn grandparent_call_is_also_a_base_call() {
        // Chain: Type10 -> [10, 20, 30] (30 is the grandparent)
        let mut chain = HashMap::new();
        chain.insert(10, vec![10, 20, 30]);
        let table = this_table(&[]);
        let m = instance_mref("Init", 30); // grandparent
        let insns = vec![call_insn(m, 0)];
        let ctx = ctx_with_chain(&insns, &table, 10, &chain);

        let (recv, name, _) = ctx.call_parts(0, 0).expect("call_parts should succeed");
        assert!(
            matches!(recv.as_deref(), Some(Expr::Var(n)) if n == "base"),
            "grandparent call should also be `base`, got {recv:?}"
        );
        assert_eq!(name, "Init");
    }

    /// Call on an unrelated type (not in the chain) is NOT a base call.
    #[test]
    fn unrelated_type_call_is_not_a_base_call() {
        let mut chain = HashMap::new();
        chain.insert(10, vec![10, 20]);
        let table = this_table(&[]);
        let m = instance_mref("Other", 99); // not in chain
        let insns = vec![call_insn(m, 0)];
        let ctx = ctx_with_chain(&insns, &table, 10, &chain);

        let (recv, _, _) = ctx.call_parts(0, 0).expect("call_parts should succeed");
        assert!(
            !matches!(recv.as_deref(), Some(Expr::Var(n)) if n == "base"),
            "unrelated type call should not become `base`, got {recv:?}"
        );
    }

    /// No parent chain metadata → conservative: no rewrite.
    #[test]
    fn no_parent_chain_means_no_rewrite() {
        let chain = HashMap::new(); // empty — no ancestry info
        let table = this_table(&[]);
        let m = instance_mref("OnEnter", 20);
        let insns = vec![call_insn(m, 0)];
        let ctx = ctx_with_chain(&insns, &table, 10, &chain);

        let (recv, _, _) = ctx.call_parts(0, 0).expect("call_parts should succeed");
        assert!(
            !matches!(recv.as_deref(), Some(Expr::Var(n)) if n == "base"),
            "without ancestry metadata, must not rewrite, got {recv:?}"
        );
    }
}

// ---------------------------------------------------------------------------
// Renderer cleanup tests: negation spelling, early-exit layout, indentation
// ---------------------------------------------------------------------------
#[cfg(test)]
mod renderer_cleanup_tests {
    use super::*;

    fn v(n: &str) -> Expr {
        Expr::Var(n.into())
    }
    fn int(n: i64) -> Expr {
        Expr::Int(n)
    }
    fn cmp(k: CmpKind, a: Expr, b: Expr) -> Expr {
        Expr::Cmp(k, Box::new(a), Box::new(b))
    }
    fn not(e: Expr) -> Expr {
        Expr::Not(Box::new(e))
    }
    fn call(name: &str) -> Expr {
        Expr::Call {
            recv: None,
            name: name.into(),
            args: vec![],
        }
    }
    fn render(e: &Expr) -> String {
        let mut s = String::new();
        e.render(&mut s);
        s
    }

    #[test]
    fn double_negation_of_a_call_collapses() {
        assert_eq!(render(&not(not(call("fn")))), "fn()");
        // Odd chains leave exactly one `!`.
        assert_eq!(render(&not(not(not(call("fn"))))), "!fn()");
        assert_eq!(render(&not(not(call("fn")))), "fn()");
    }

    #[test]
    fn double_negation_of_a_comparison_collapses() {
        let e = not(not(cmp(CmpKind::Lt, v("a"), v("b"))));
        assert_eq!(render(&e), "a < b");
    }

    #[test]
    fn negated_integer_ordering_renders_the_complement() {
        let e = not(cmp(CmpKind::Gt, v("v66"), v("centeredContentID")));
        assert_eq!(render(&e), "v66 <= centeredContentID");
        // Pointer derefs are non-float too.
        let deref = Expr::RawDeref(Box::new(v("p")), 24, 0);
        let e = not(cmp(CmpKind::Lt, deref, int(1)));
        assert_eq!(render(&e), "*(nint*)(p +24) >= 1");
    }

    #[test]
    fn negated_equality_renders_the_complement_for_unknown_types() {
        let field = Expr::Field(Box::new(Expr::This), "flag".into());
        let e = not(cmp(CmpKind::Eq, field, int(0)));
        assert_eq!(render(&e), "this.flag != 0");
    }

    #[test]
    fn negated_float_ordering_keeps_the_exact_not() {
        // NaN: !(x >= 30f) is TRUE while x < 30f is false. Both the literal
        // and the vs-register name prove a float, so the spelling must not
        // change.
        let e = not(cmp(CmpKind::Ge, v("in_vs33"), Expr::Float(30.0)));
        assert_eq!(render(&e), "!(in_vs33 >= 30f)");
        let e = not(cmp(CmpKind::Gt, v("vs0"), Expr::Double(0.0)));
        assert_eq!(render(&e), "!(vs0 > 0.0)");
    }

    #[test]
    fn collapsed_double_negation_reports_the_operands_precedence() {
        // `1 + a < b` would re-associate; the effective precedence of `!!cmp`
        // is comparison precedence, so the parent must parenthesize.
        let e = Expr::Bin(
            BinOp::Add,
            Box::new(int(1)),
            Box::new(not(not(cmp(CmpKind::Lt, v("a"), v("b"))))),
        );
        assert_eq!(render(&e), "1 + (a < b)");
    }

    #[test]
    fn non_comparison_negation_keeps_minimal_parens() {
        let and = Expr::Bin(BinOp::AndAlso, Box::new(cmp(CmpKind::Eq, v("a"), int(0))), Box::new(cmp(CmpKind::Eq, v("b"), int(0))));
        assert_eq!(render(&not(and)), "!(a == 0 && b == 0)");
    }

    #[test]
    fn else_return_becomes_an_early_exit_guard() {
        let s = Stmt::If {
            cond: cmp(CmpKind::Ne, v("x"), int(0)),
            then_body: vec![
                Stmt::Assign("y".into(), None, int(1)),
                Stmt::Eval(call("fn")),
            ],
            else_body: vec![Stmt::Return(None)],
        };
        assert_eq!(
            render_stmts(&[s]),
            "if (x == 0) return;\ny = 1;\nfn();\n"
        );
    }

    #[test]
    fn early_exit_is_refused_when_the_then_arm_has_a_label() {
        let s = Stmt::If {
            cond: cmp(CmpKind::Ne, v("x"), int(0)),
            then_body: vec![Stmt::Label("L1".into()), Stmt::Assign("y".into(), None, int(1))],
            else_body: vec![Stmt::Return(None)],
        };
        let out = render_stmts(&[s]);
        assert!(out.contains("if (x != 0)"), "{out}");
        assert!(out.contains("L1:"), "label definition must survive: {out}");
        assert!(out.contains("} else"), "braced if/else kept: {out}");
        assert!(!out.contains("return;\ny = 1;"), "nothing hoisted past a label: {out}");
    }

    #[test]
    fn early_exit_is_refused_when_the_then_arm_terminates() {
        let s = Stmt::If {
            cond: cmp(CmpKind::Ne, v("x"), int(0)),
            then_body: vec![Stmt::Return(None)],
            else_body: vec![Stmt::Return(None)],
        };
        let out = render_stmts(&[s]);
        assert!(out.contains("} else"), "both-returning arms keep their shape: {out}");
    }

    #[test]
    fn early_exit_is_refused_when_a_declaration_would_be_hoisted() {
        let s = Stmt::If {
            cond: cmp(CmpKind::Ne, v("x"), int(0)),
            then_body: vec![Stmt::Assign("y".into(), Some("int".into()), int(1))],
            else_body: vec![Stmt::Return(None)],
        };
        let out = render_stmts(&[s]);
        assert!(out.contains("} else"), "declaration stays block-scoped: {out}");
    }

    #[test]
    fn early_exit_is_refused_in_an_else_if_position() {
        let inner = Stmt::If {
            cond: cmp(CmpKind::Ne, v("x"), int(0)),
            then_body: vec![Stmt::Assign("y".into(), None, int(1))],
            else_body: vec![Stmt::Return(None)],
        };
        let outer = Stmt::If {
            cond: cmp(CmpKind::Ne, v("a"), int(0)),
            then_body: vec![Stmt::Eval(call("t"))],
            else_body: vec![inner],
        };
        let out = render_stmts(&[outer]);
        assert!(out.contains("else if (x != 0)"), "{out}");
        assert!(!out.contains("if (x == 0) return;"), "must not hoist past the else: {out}");
    }

    #[test]
    fn single_statement_arms_render_braceless() {
        let s = Stmt::If {
            cond: cmp(CmpKind::Ne, v("x"), int(0)),
            then_body: vec![Stmt::Return(None)],
            else_body: vec![],
        };
        assert_eq!(render_stmts(&[s]), "if (x != 0) return;\n");
    }

    #[test]
    fn double_negated_if_condition_prints_once() {
        let s = Stmt::If {
            cond: not(not(call("isActive"))),
            then_body: vec![Stmt::Assign("y".into(), None, int(1)), Stmt::Assign("z".into(), None, int(2))],
            else_body: vec![],
        };
        let out = render_stmts(&[s]);
        assert!(out.contains("if (isActive())\n"), "{out}");
        assert!(!out.contains("!("), "{out}");
    }

    #[test]
    fn switch_expression_arms_follow_the_statement_indent() {
        let sw = Expr::SwitchExpr {
            discrim: Box::new(v("d")),
            arms: vec![(int(0), int(1))],
            default_arm: Some(Box::new(int(2))),
        };
        let s = Stmt::If {
            cond: cmp(CmpKind::Ne, v("x"), int(0)),
            then_body: vec![Stmt::Assign("y".into(), None, sw)],
            else_body: vec![],
        };
        let out = render_stmts(&[s]);
        assert!(
            out.contains("\ty = d switch {\n\t\t0 => 1,\n\t\t_ => 2,\n\t};\n"),
            "arms must sit one level under the statement, not at column 1:\n{out}"
        );
    }

    #[test]
    fn else_opens_its_brace_on_the_closing_brace_line() {
        let s = Stmt::If {
            cond: cmp(CmpKind::Ne, v("x"), int(0)),
            then_body: vec![Stmt::Assign("a".into(), None, int(1))],
            else_body: vec![Stmt::Assign("b".into(), None, int(2))],
        };
        let out = render_stmts(&[s]);
        assert!(out.contains("} else {"), "{out}");
        assert!(!out.contains("} else\n{"), "{out}");
    }

    #[test]
    fn else_if_opens_its_brace_on_the_header_line() {
        let inner = Stmt::If {
            cond: cmp(CmpKind::Ne, v("y"), int(0)),
            then_body: vec![
                Stmt::Assign("a".into(), None, int(1)),
                Stmt::Assign("c".into(), None, int(3)),
            ],
            else_body: vec![],
        };
        let s = Stmt::If {
            cond: cmp(CmpKind::Ne, v("x"), int(0)),
            then_body: vec![Stmt::Assign("b".into(), None, int(2))],
            else_body: vec![inner],
        };
        let out = render_stmts(&[s]);
        assert!(out.contains("} else if (y != 0) {"), "{out}");
    }

    #[test]
    fn multi_line_statement_keeps_braces() {
        let sw = Expr::SwitchExpr {
            discrim: Box::new(v("d")),
            arms: vec![(int(0), int(1))],
            default_arm: None,
        };
        let s = Stmt::If {
            cond: cmp(CmpKind::Ne, v("x"), int(0)),
            then_body: vec![Stmt::Assign("y".into(), None, sw)],
            else_body: vec![],
        };
        let out = render_stmts(&[s]);
        assert!(out.contains("if (x != 0)\n{\n\ty = d switch {"), "{out}");
    }
}

fn obj_census_text(ctx: &MethodCtx, rva: u64, obj_lis: &HashSet<usize>) -> String {
    let mut versions_by_li: HashMap<usize, Vec<u32>> = HashMap::new();
    for (&v, &li) in &ctx.table.index_of {
        versions_by_li.entry(li).or_default().push(v);
    }
    let mut lis: Vec<usize> = obj_lis.iter().copied().collect();
    lis.sort_unstable();
    let mut out = String::new();
    for li in lis {
        let Some(info) = ctx.table.infos.get(li) else {
            continue;
        };
        let Some(vers) = versions_by_li.get(&li) else {
            continue;
        };
        let vset: HashSet<u32> = vers.iter().copied().collect();
        if vset.is_empty() {
            continue;
        }
        let mut defs: HashMap<&'static str, usize> = HashMap::new();
        let mut ndefs = 0usize;
        for &v in vers {
            if let Some(sites) = ctx.def_sites.get(&v) {
                for &d in sites {
                    ndefs += 1;
                    *defs.entry(def_kind(&ctx.insns[d])).or_default() += 1;
                }
            }
        }
        let mut reads: HashMap<&'static str, usize> = HashMap::new();
        for insn in ctx.insns {
            let dst = insn.dest().and_then(|d| d.as_local());
            let def_pos = match &insn.op {
                Op::Move => Some(0),
                Op::Call | Op::CallVoid => Some(1),
                _ => None,
            };
            for (pos, op) in insn.operands.iter().enumerate() {
                if Some(pos) == def_pos {
                    continue;
                }
                if let (Some(d), Operand::Local(v)) = (dst, op) {
                    if *v == d {
                        continue;
                    }
                }
                let role: &'static str = match &insn.op {
                    Op::Call | Op::CallVoid => {
                        if pos == 2 {
                            "call_recv"
                        } else if pos >= 3 {
                            "call_arg"
                        } else {
                            "call_target"
                        }
                    }
                    Op::Move => "src",
                    Op::Compare(_) => "cmp",
                    Op::CondJump(_) => "cond",
                    Op::Return => "return",
                    Op::Throw => "throw",
                    Op::Arith(_) => "arith",
                    _ => "other",
                };
                walk_operand_census(op, role, &vset, &mut reads);
            }
        }
        let addr = vers.iter().any(|v| ctx.address_taken.contains(v));
        let sret = vers.iter().any(|v| ctx.sret_buffers.contains(v));
        let mut roots: HashMap<&'static str, usize> = HashMap::new();
        for &v in vers {
            let mut seen = HashSet::new();
            root_kinds(ctx, v, 0, &mut seen, &mut roots);
        }
        out.push_str(&format!(
            "{:#x}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{:?}\n",
            rva,
            li,
            vers.len(),
            ndefs,
            fmt_counts(&defs),
            reads.values().sum::<usize>(),
            fmt_counts(&reads),
            addr as u8,
            sret as u8,
            info.slot_origin,
            fmt_counts(&roots),
            info.ty,
        ));
    }
    out
}

fn def_kind(insn: &Insn) -> &'static str {
    match &insn.op {
        Op::Call | Op::CallVoid => match insn.operands.first() {
            Some(Operand::Method(_)) => "call_named",
            Some(Operand::Immediate(a)) => {
                if super::runtime_helpers::role_of(*a as u64).is_some() {
                    "call_helper"
                } else {
                    "call_imm"
                }
            }
            _ => "call_other",
        },
        Op::Move => match insn.operands.get(1) {
            Some(Operand::Local(_)) => "alias",
            Some(Operand::Field(_)) => "field_static",
            Some(Operand::InstanceField { .. }) => "field_inst",
            Some(Operand::Memory {
                index: Some(_), ..
            }) => "mem_index",
            Some(Operand::Memory { .. }) => "mem",
            Some(Operand::ArrayAccess { .. }) => "array_access",
            Some(Operand::ArrayLength(_)) => "array_len",
            Some(Operand::Immediate(0)) => "zero",
            Some(Operand::Immediate(_)) => "imm",
            Some(Operand::AddressOf(_)) => "addr",
            Some(Operand::Type(_)) => "type",
            _ => "move_other",
        },
        Op::Phi => "phi",
        Op::NewObj(_) => "newobj",
        Op::NewArr(_) => "newarr",
        _ => "other",
    }
}

fn walk_operand_census(
    op: &Operand,
    role: &'static str,
    vset: &HashSet<u32>,
    out: &mut HashMap<&'static str, usize>,
) {
    match op {
        Operand::Local(v) => {
            if vset.contains(v) {
                *out.entry(role).or_default() += 1;
            }
        }
        Operand::Memory { base, index, .. } => {
            walk_operand_census(base, "mem_base", vset, out);
            if let Some(i) = index {
                walk_operand_census(i, "mem_index", vset, out);
            }
        }
        Operand::InstanceField { base, .. } => {
            walk_operand_census(base, "field_recv", vset, out);
        }
        Operand::AddressOf(inner) => walk_operand_census(inner, "addr", vset, out),
        Operand::ArrayAccess { array, index } => {
            walk_operand_census(array, "array", vset, out);
            walk_operand_census(index, "array_index", vset, out);
        }
        Operand::ArrayLength(a) => walk_operand_census(a, "array_len", vset, out),
        _ => {}
    }
}

fn root_kinds(
    ctx: &MethodCtx,
    v: u32,
    depth: usize,
    seen: &mut HashSet<u32>,
    out: &mut HashMap<&'static str, usize>,
) {
    if depth > 16 || !seen.insert(v) {
        *out.entry("cycle").or_default() += 1;
        return;
    }
    let sites = ctx.def_sites.get(&v).filter(|s| !s.is_empty());
    let Some(sites) = sites else {
        classify_leaf(ctx, v, out);
        seen.remove(&v);
        return;
    };
    for &d in sites {
        let insn = &ctx.insns[d];
        match &insn.op {
            Op::Move => match insn.operands.get(1) {
                Some(Operand::Local(src)) if *src != v => {
                    root_kinds(ctx, *src, depth + 1, seen, out);
                }
                Some(Operand::Field(_)) | Some(Operand::InstanceField { .. }) => {
                    *out.entry("field").or_default() += 1;
                }
                Some(Operand::Memory { .. })
                | Some(Operand::ArrayAccess { .. })
                | Some(Operand::ArrayLength(_)) => {
                    *out.entry("mem").or_default() += 1;
                }
                Some(Operand::Immediate(0)) => {
                    *out.entry("zero").or_default() += 1;
                }
                Some(Operand::Immediate(_)) => {
                    *out.entry("imm").or_default() += 1;
                }
                Some(Operand::AddressOf(_)) => {
                    *out.entry("addr").or_default() += 1;
                }
                _ => {
                    *out.entry("other").or_default() += 1;
                }
            },
            Op::Call | Op::CallVoid => match insn.operands.first() {
                Some(Operand::Method(_)) => {
                    *out.entry("call_named").or_default() += 1;
                }
                Some(Operand::Immediate(a)) => {
                    if super::runtime_helpers::role_of(*a as u64).is_some() {
                        *out.entry("call_helper").or_default() += 1;
                    } else {
                        *out.entry("call_imm").or_default() += 1;
                    }
                }
                _ => {
                    *out.entry("call_other").or_default() += 1;
                }
            },
            Op::Phi => {
                let mut any = false;
                for op in &insn.operands {
                    if let Operand::Local(src) = op {
                        if *src != v {
                            root_kinds(ctx, *src, depth + 1, seen, out);
                            any = true;
                        }
                    }
                }
                if !any {
                    *out.entry("phi_leaf").or_default() += 1;
                }
            }
            Op::NewObj(_) => {
                *out.entry("newobj").or_default() += 1;
            }
            Op::NewArr(_) => {
                *out.entry("newarr").or_default() += 1;
            }
            _ => {
                *out.entry("other").or_default() += 1;
            }
        }
    }
    seen.remove(&v);
}

fn classify_leaf(ctx: &MethodCtx, v: u32, out: &mut HashMap<&'static str, usize>) {
    if let Some(&li) = ctx.table.index_of.get(&v) {
        let info = &ctx.table.infos[li];
        if info.is_this {
            *out.entry("root_this").or_default() += 1;
            return;
        }
        if info.is_param.is_some() {
            *out.entry("root_param").or_default() += 1;
            return;
        }
        if MethodCtx::stack_cell_name(&info.slot_origin).is_some() {
            *out.entry("root_stack").or_default() += 1;
            return;
        }
        if ctx.entry_register_name(v, info).is_some() {
            *out.entry("root_entry").or_default() += 1;
            return;
        }
    }
    *out.entry("root_undef").or_default() += 1;
}

fn fmt_counts(m: &HashMap<&'static str, usize>) -> String {
    let mut v: Vec<(&str, usize)> = m.iter().map(|(k, c)| (*k, *c)).collect();
    v.sort_by_key(|(k, _)| *k);
    v.into_iter()
        .map(|(k, c)| format!("{k}:{c}"))
        .collect::<Vec<_>>()
        .join(",")
}

#[cfg(test)]
mod eh_merge_tests {
    use super::*;
    use crate::recovery::exceptions::{Clause, EhRegion};

    fn nop(a: u64) -> Insn {
        Insn::nop(a)
    }
    fn jump(a: u64, t: usize) -> Insn {
        Insn::new(Op::Jump(t), vec![], a)
    }

    /// Two landing pads (0x1008 in B1, 0x1020 in B4) that both trampoline
    /// onto the SAME dispatcher root (B3), with ordinary code in B2 between
    /// them — the shape every multi-call-site try in this corpus has.
    fn two_rows_one_dispatcher() -> (Vec<Insn>, StructuredCfg) {
        let insns = vec![
            nop(0x1000),
            jump(0x1004, 2),
            nop(0x1008),
            jump(0x100c, 6),
            Insn::new(
                Op::Move,
                vec![Operand::Local(1), Operand::Immediate(7)],
                0x1010,
            ),
            jump(0x1014, 6),
            Insn::new(Op::Compare(CompareKind::Equal), vec![], 0x1018),
            Insn::new(Op::CondJump(9), vec![], 0x101c),
            nop(0x1020),
            jump(0x1024, 6),
        ];
        let sc = analyze_blocks(&insns);
        (insns, sc)
    }

    fn catch_row(s: u64, e: u64, pad: u64) -> EhRegion {
        EhRegion::new(
            s,
            e,
            pad,
            vec![Clause::Catch {
                name: "Il2CppExceptionWrapper /* managed catch */".into(),
            }],
        )
    }

    /// E3: two call-site rows of ONE try share a handler, and the handler is a
    /// selector DISPATCHER, not a trampoline. The old fence required every
    /// block between the two pads to be a trampoline onto one root, so it
    /// refused the pair; each row then folded alone and the second rendered
    /// `catch { goto L<pad> }` because the pad was already consumed.
    #[test]
    fn rows_sharing_a_dispatcher_root_are_one_try() {
        let (insns, sc) = two_rows_one_dispatcher();
        let rows = [catch_row(0x2000, 0x2010, 0x1008), catch_row(0x2010, 0x2020, 0x1020)];
        let merged = merge_eh_regions(&rows, &sc, &insns);
        assert_eq!(merged.len(), 1, "one handler root = one try: {merged:?}");
        assert_eq!((merged[0].try_start, merged[0].try_end), (0x2000, 0x2020));
        assert_eq!(merged[0].landing_pad, 0x1008, "the first row names the try");
    }

    /// Rows with different handler roots are different tries and must never
    /// fuse, however adjacent their ranges are.
    #[test]
    fn rows_with_different_roots_stay_separate() {
        let (insns, sc) = two_rows_one_dispatcher();
        // 0x1010 is B2, which does work, so its root is itself — not the
        // dispatcher B3 that the first row's pad funnels into.
        let rows = [catch_row(0x2000, 0x2010, 0x1008), catch_row(0x2010, 0x2020, 0x1010)];
        let merged = merge_eh_regions(&rows, &sc, &insns);
        assert_eq!(merged.len(), 2, "different roots must not merge: {merged:?}");
    }

    /// Rows of one try are address-ordered; an overlapping pair must not fuse
    /// (that would reorder control flow).
    #[test]
    fn overlapping_rows_do_not_merge() {
        let (insns, sc) = two_rows_one_dispatcher();
        let rows = [catch_row(0x2000, 0x2020, 0x1008), catch_row(0x2010, 0x2030, 0x1020)];
        let merged = merge_eh_regions(&rows, &sc, &insns);
        assert_eq!(merged.len(), 2, "overlap must not merge: {merged:?}");
    }

    /// E8: a chain with no typed arm is the compiler's terminate guard, not a
    /// C# catch. It must not fold a `try`/`catch` around code that terminates.
    #[test]
    fn a_chain_with_no_typed_arm_is_a_terminate_guard() {
        assert!(is_terminate_guard(&EhRegion::new(
            0,
            1,
            0,
            vec![Clause::CatchAll]
        )));
        assert!(!is_terminate_guard(&EhRegion::new(
            0,
            1,
            0,
            vec![Clause::Catch { name: "w".into() }, Clause::Cleanup]
        )));
        assert!(!is_terminate_guard(&EhRegion::new(
            0,
            1,
            0,
            vec![Clause::Cleanup]
        )));
    }
}

// ---------------------------------------------------------------------------
// Shared-return-tail duplication
// ---------------------------------------------------------------------------

/// The compiler merges every `return x;` of a method into ONE shared epilogue
/// and the structurer used to emit that epilogue once, turning every other
/// return site into `goto L`. `duplicable_tail` inlines a small
/// straight-line chain that ends in Return/Throw at the jump site instead.
#[cfg(test)]
mod shared_tail_tests {
    use super::*;

    fn table(ids: &[u32]) -> LocalTable {
        let mut t = LocalTable::default();
        for (i, id) in ids.iter().enumerate() {
            t.infos.push(super::super::locals::LocalInfo {
                // Distinct origins: the synthetic IR uses one slot per value, so
                // a shared origin would give every local the SAME rendered name
                // and let text-based dedup passes fold genuinely different
                // conditions into one.
                slot_origin: format!("x{}", i + 9),
                ty: ManagedType::Unknown,
                is_this: false,
                is_param: None,
                param_comp: None,
                is_incoming_arg: false,
                is_call_clobber: false,
                is_return_buffer: false,
            });
            t.index_of.insert(*id, i);
        }
        t
    }

    fn render(insns: Vec<Insn>) -> String {
        let ids: Vec<u32> = (1..=6).collect();
        let ir = super::super::RecoveredIr {
            insns,
            table: table(&ids),
            returns_value: false,
            base_rva: 0x9000,
        };
        render_method_csharp(&ir, "M", true, &[], &ManagedType::Unknown, -1)
    }

    /// A local defined by an allocation and read at a use site must have its
    /// allocation STATEMENT. The use site never inlines a `new` (that would
    /// allocate a second object and abandon the first), so it references the
    /// name — and with no statement the name is undefined. That is the
    /// `def-dropped:NewObj` class: `return this.Set<object>(v62);` with no
    /// `v62 = new JSONObject();` anywhere in the body.
    #[test]
    fn an_allocation_read_at_a_use_site_is_defined() {
        let insns = vec![
            Insn::new(
                Op::NewObj(Some(crate::recovery::ir::NamedTypeRef {
                    ty: crate::recovery::types::NamedType {
                        namespace: "HoudiniEngineUnity".into(),
                        name: "JSONObject".into(),
                        assembly: None,
                        type_def_index: 7398,
                    },
                })),
                vec![Operand::Local(5)],
                0x9000,
            ),
            Insn::new(
                Op::Call,
                vec![Operand::imm(0x2222), Operand::Local(6), Operand::Local(5)],
                0x9004,
            ),
            Insn::new(Op::Return, vec![], 0x9008),
        ];
        let out = render(insns);
        assert!(
            out.contains("new JSONObject()"),
            "the allocation must reach the text:\n{out}"
        );
        assert!(
            !out.contains("v5"),
            "a use site must not reference an unbound allocation name:\n{out}"
        );
    }


    /// Two guards, one shared `call; return` epilogue. The epilogue is emitted
    /// inside the FIRST guard's arm, so the second guard's edge to it is a
    /// backward jump to an already-emitted block — the exact shape of the
    /// canary 0x18141F0. The source had two copies, so both must be emitted.
    #[test]
    fn a_shared_return_tail_is_duplicated_not_jumped_to() {
        let insns = vec![
            //  B0: if (v1 != 0) goto B3
            Insn::new(
                Op::Compare(CompareKind::NotEqual),
                vec![Operand::Local(3), Operand::Local(1), Operand::imm(0)],
                0x9000,
            ),
            Insn::new(Op::CondJump(5), vec![Operand::Local(3)], 0x9004),
            //  B1: if (v2 != 0) goto B3
            Insn::new(
                Op::Compare(CompareKind::NotEqual),
                vec![Operand::Local(4), Operand::Local(2), Operand::imm(0)],
                0x9008,
            ),
            Insn::new(Op::CondJump(5), vec![Operand::Local(4)], 0x900c),
            //  B2: goto B4
            Insn::new(Op::Jump(7), vec![], 0x9010),
            //  B3: the shared tail — v5 = fn_2222(v1); goto B4
            Insn::new(
                Op::Call,
                vec![Operand::imm(0x2222), Operand::Local(5), Operand::Local(1)],
                0x9014,
            ),
            Insn::new(Op::Jump(7), vec![], 0x9018),
            //  B4: return
            Insn::new(Op::Return, vec![], 0x901c),
        ];
        let out = render(insns);
        assert!(
            !out.contains("goto"),
            "the shared tail must be inlined at the second site, not jumped to:\n{out}"
        );
        assert_eq!(
            out.matches("fn_2222(").count(),
            2,
            "both source sites must carry the tail:\n{out}"
        );
    }



    /// The same shape, but the chain is CONDITIONAL — it is not a tail, it is
    /// structure of its own, so the jump must survive (the copy would need its
    /// own arms and could duplicate a side effect on one path).
    #[test]
    fn a_conditional_chain_is_not_duplicated() {
        let insns = vec![
            //  B0: if (v1 != 0) goto B3
            Insn::new(
                Op::Compare(CompareKind::NotEqual),
                vec![Operand::Local(3), Operand::Local(1), Operand::imm(0)],
                0x9000,
            ),
            Insn::new(Op::CondJump(5), vec![Operand::Local(3)], 0x9004),
            //  B1: if (v2 != 0) goto B3
            Insn::new(
                Op::Compare(CompareKind::NotEqual),
                vec![Operand::Local(4), Operand::Local(2), Operand::imm(0)],
                0x9008,
            ),
            Insn::new(Op::CondJump(5), vec![Operand::Local(4)], 0x900c),
            //  B2: goto B4
            Insn::new(Op::Jump(7), vec![], 0x9010),
            //  B3: the shared tail — v5 = fn_2222(v1); goto B4
            Insn::new(
                Op::Call,
                vec![Operand::imm(0x2222), Operand::Local(5), Operand::Local(1)],
                0x9014,
            ),
            Insn::new(Op::CondJump(7), vec![Operand::Local(5)], 0x9018),
            //  B4: return
            Insn::new(Op::Return, vec![], 0x901c),
        ];
        let out = render(insns);
        // The tail must not be COPIED (that is what this test is about): a
        // conditional tail would need its own arms at each site and could run
        // its side effect on one path only. Whether the surviving structure is
        // a jump or a folded guard is the structurer's choice — the fold that
        // removes the jump is sound as long as the call survives exactly once.
        assert_eq!(
            out.matches("fn_2222(").count(),
            1,
            "a conditional tail must not be duplicated:\n{out}"
        );
        assert!(
            out.contains("fn_2222("),
            "the tail's call must survive the guard fold:\n{out}"
        );
        // ...and no dangling reference is left behind. The rejected tail was
        // the binding's only reader, so the dead `v4 = …` store is dropped by
        // `dead_write_only`; the call itself must survive, and nothing may
        // still spell the unbound name.
        assert!(
            !out.contains("v4"),
            "the rejected tail must not leave an unbound name:\n{out}"
        );
    }
}


#[cfg(test)]
mod type_text_tests {
    use super::expand_arity;

    /// A backtick is metadata arity syntax and cannot appear in a C#
    /// identifier, so a type rendered from the bare definition does not
    /// compile. With no instantiation available the metadata's own
    /// shared-generic argument is `object`.
    #[test]
    fn an_open_generic_expands_to_object_arguments() {
        assert_eq!(expand_arity("Dictionary`2"), "Dictionary<object, object>");
        assert_eq!(expand_arity("List`1"), "List<object>");
        assert_eq!(expand_arity("Action`3"), "Action<object, object, object>");
    }

    #[test]
    fn a_closed_or_plain_name_is_untouched() {
        assert_eq!(expand_arity("Dictionary<int, object>"), "Dictionary<int, object>");
        assert_eq!(expand_arity("Token"), "Token");
        assert_eq!(expand_arity("Dictionary`0"), "Dictionary`0");
        assert_eq!(expand_arity("Dictionary`x"), "Dictionary`x");
    }
}

#[cfg(test)]
mod switch_group_tests {
    use super::*;

    fn render(s: &Stmt) -> String {
        let mut r = Renderer::new();
        r.stmt(s);
        r.out
    }

    #[test]
    fn identical_adjacent_arms_share_one_label_run() {
        let sw = Stmt::Switch {
            disc: "x".into(),
            cases: vec![
                (1, vec![Stmt::Return(None)]),
                (2, vec![Stmt::Return(None)]),
                (3, vec![Stmt::Break]),
            ],
            tail: vec![],
            default: None,
        };
        let out = render(&sw);
        assert_eq!(out.matches("return;").count(), 1, "{out}");
        let one = out.find("case 1:").unwrap();
        let two = out.find("case 2:").unwrap();
        let ret = out.find("return;").unwrap();
        assert!(one < two && two < ret, "{out}");
    }

    #[test]
    fn a_trailing_default_with_the_same_body_joins_the_run() {
        let sw = Stmt::Switch {
            disc: "x".into(),
            cases: vec![(9, vec![Stmt::Break]), (10, vec![Stmt::Break])],
            tail: vec![],
            default: Some(vec![Stmt::Break]),
        };
        let out = render(&sw);
        assert_eq!(out.matches("break;").count(), 1, "{out}");
        assert!(out.find("case 9:").unwrap() < out.find("case 10:").unwrap());
        assert!(out.find("case 10:").unwrap() < out.find("default:").unwrap());
    }
}

#[cfg(test)]
mod new_result_guard_tests {
    use super::*;

    fn new_assign(name: &str) -> Stmt {
        Stmt::Assign(name.into(), None, Expr::NewObj("T".into(), vec![]))
    }

    fn guard(name: &str) -> Stmt {
        Stmt::If {
            cond: Expr::Cmp(
                CmpKind::Eq,
                Box::new(Expr::Var(name.into())),
                Box::new(Expr::Null),
            ),
            then_body: vec![Stmt::Return(None)],
            else_body: vec![],
        }
    }

    #[test]
    fn a_null_guard_on_a_fresh_allocation_is_removed() {
        let mut s = vec![new_assign("x"), guard("x")];
        assert_eq!(strip_new_result_guards(&mut s), 1);
        assert_eq!(s.len(), 1);
    }

    #[test]
    fn a_guard_after_unrelated_statements_is_removed() {
        let mut s = vec![
            new_assign("x"),
            Stmt::If {
                cond: Expr::Cmp(
                    CmpKind::Eq,
                    Box::new(Expr::StaticField("T".into(), "Init".into())),
                    Box::new(Expr::Int(0)),
                ),
                then_body: vec![Stmt::Assign(
                    "boxed".into(),
                    Some("var".into()),
                    Expr::Call {
                        recv: None,
                        name: "Box".into(),
                        args: vec![Expr::Var("y".into())],
                    },
                )],
                else_body: vec![],
            },
            guard("x"),
        ];
        assert_eq!(strip_new_result_guards(&mut s), 1);
        assert_eq!(s.len(), 2);
    }

    #[test]
    fn a_guard_after_the_local_is_reassigned_is_kept() {
        let mut s = vec![
            new_assign("x"),
            Stmt::Assign("x".into(), None, Expr::Null),
            guard("x"),
        ];
        assert_eq!(strip_new_result_guards(&mut s), 0);
        assert_eq!(s.len(), 3);
    }

    #[test]
    fn a_guard_on_an_ordinary_local_is_kept() {
        let mut s = vec![Stmt::Eval(Expr::Var("x".into())), guard("x")];
        assert_eq!(strip_new_result_guards(&mut s), 0);
        assert_eq!(s.len(), 2);
    }
}
